import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { AccessToken, Input } from '../../types';
import { useAsyncAction } from '../hooks/useAsyncAction';
import { AxiosRequestConfig } from 'axios';
import { httpClient } from '../../common/httpClient';

export interface RefreshTokenToConsoleMutation {
  refreshTokenToConsole: AccessToken;
}

export interface RefreshTokenInput {
  refreshToken: string;
  isFirstLogin?: boolean;
}

const refreshTokenToConsoleMutation = gql`
  mutation refreshTokenToConsole($input: RefreshTokenInput!) {
    refreshTokenToConsole(input: $input) {
      accessToken
      refreshToken
      expiresIn
      tokenType
    }
  }
`;

export function useRefreshTokenToConsoleMutation(
  options?: MutationHookOptions<RefreshTokenToConsoleMutation, Input<RefreshTokenInput>>,
) {
  return useMutation(refreshTokenToConsoleMutation, options);
}

export function useRefreshTokenToConsoleRest(config?: AxiosRequestConfig) {
  const status = useAsyncAction(
    async (
      input: RefreshTokenInput,
    ): Promise<RefreshTokenToConsoleMutation['refreshTokenToConsole']> => {
      const result = await httpClient.post('/v1/auth/refresh-token', input, config);
      return result.data;
    },
  );

  return status;
}
