export enum Os {
  Desktop = 'desktop',
  Web = 'web',
  Sdk = 'sdk',
}

export interface OrganizationProduct {
  name: string;
  sources?: string[];
  contentSources?: string[];
  isDefaultVcUserProduct?: boolean;
}

export enum IdentityProvider {
  Auth0 = 'Auth0',
  Auth0InteractiveSso = 'Auth0InteractiveSSO',
  SeamlessLogin = 'SeamlessLogin',
}

export enum OrganizationTag {
  VimTest = 'VimTest',
  AppTest = 'AppTest',
  ClinicTest = 'ClinicTest',
}

export enum OrganizationRelationTypeV2 {
  Owned = 'owned',
  DataConsuming = 'dataConsuming',
  AppConsuming = 'appConsuming',
}

export interface Organization {
  id: number;
  name: string;
  createdAt?: Date;
  ehrSystem?: string;
  ehrUrl?: string;
  ehrOS?: Os;
  ehrIdentifier?: string;
  config?: Record<string, unknown>;
  products: OrganizationProduct[];
  namespaceName?: string;
  tin?: string;
  tins?: string[];
  npi?: string;
  identityProvider?: IdentityProvider;
  organizationKey?: string;
  tag?: OrganizationTag;
  isSeamlessLoginAutoApproved?: boolean;
  shouldAutoCreatePotentialUsers?: boolean;
  accountId: number;
  accountName?: string;
  account?: { name: string };
  isOptOutFromVC?: boolean;
  relationTypes?: OrganizationRelationTypeV2[];
}

export type ConsoleUserOrganization = {
  id: number;
  name: string;
  createdAt?: Date;
  ehrUrl?: string;
  ehrOS?: Os;
  products: OrganizationProduct[];
  tins?: string[];
  npi?: string;
  organizationKey?: string;
  tag?: OrganizationTag;
  accountId: number;
  accountName?: string;
  isOptOutFromVC?: boolean;
  relationTypes?: OrganizationRelationTypeV2[];
};

export type OrganizationListItem = Pick<Organization, 'id' | 'name'>;
