import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { Input, UserType } from '../../types';
import { AxiosRequestConfig } from 'axios';
import { httpClient } from '../../common/httpClient';
import { useAsyncAction } from '../hooks/useAsyncAction';

export interface SendPasswordResetEmailMutation {
  sendPasswordResetEmail: string;
}

export interface SendPasswordResetEmailInput {
  email: string;
  userType?: UserType;
  userTypes?: UserType[];
}

const sendPasswordResetEmailMutation = gql`
  mutation sendPasswordResetEmail($input: SendPasswordResetEmailInput!) {
    sendPasswordResetEmail(input: $input)
  }
`;

export function useSendPasswordResetEmailMutation(
  options?: MutationHookOptions<SendPasswordResetEmailMutation, Input<SendPasswordResetEmailInput>>,
) {
  return useMutation(sendPasswordResetEmailMutation, options);
}

export function useSendPasswordResetEmailRest(config?: AxiosRequestConfig) {
  const status = useAsyncAction(
    async (
      input: SendPasswordResetEmailInput,
    ): Promise<SendPasswordResetEmailMutation['sendPasswordResetEmail']> => {
      const result = await httpClient.post('/v1/users/reset-password-email', input, config);
      return result.data;
    },
  );

  return status;
}
