import { DataSource } from './data-source';
import { AddApplicationMode } from './marketplaceSettings';

export type Account = {
  id: number;
  createdAt: Date;
  updatedAt: Date;
  name: string;
  address?: string;
  phoneNumber?: string;
  tin?: string;
  privileges?: AccountPrivileges[];
  managedBy?: number;
  applications?: string[];
  isActive?: boolean;
  doNotContact?: boolean;
  isTest?: boolean;
  accountAuth?: AccountAuth;
  lastActivationStatusChangeMetadata?: LastActivationStatusChangeMetadata;
};

export interface AccountAuth {
  clientId?: string;
  clientSecret?: string;
}

export interface AccountRelation {
  relationType: AccountsRelationType;
  relatedAccountId: number;
  // eslint-disable-next-line @typescript-eslint/naming-convention
  __typename?: string;
}

export enum AccountsRelationType {
  ManagedBy = 'managedBy',
  ConsumesContentFrom = 'consumesContentFrom',
}

export type AccountConfig = {
  enableCDEForOrg?: boolean;
  activateCDEForUsers?: boolean;
  enableSeamlessAutoApprove?: boolean;
  enableAutoCreatePotentialUsers?: boolean;
  marketplaceSettings?: {
    addApplicationMode?: AddApplicationMode;
    showMarketplaceToUsers?: boolean;
    showConsoleMarketplaceToUsers?: boolean;
  };
  mailForCDEUpdates?: string;
};

export interface EnrichedAccount extends Omit<Account, 'managedBy'> {
  managingAccountMetadata?: Partial<Account>;
  isManagingOtherAccounts?: boolean;
  activationStatus?: AccountActivationStatus;
  dataSource?: DataSource;
  providerOrganizationIds?: number[];
  applications?: string[];
  relations?: AccountRelation[];
  config?: AccountConfig;
  tosSignatureDate?: Date;
}

export enum AccountPrivileges {
  CAN_MANAGE_ACCOUNTS = 'canManageAccounts',
  CAN_OWN_PROVIDER_ORGANIZATIONS = 'canOwnProviderOrganizations',
  CAN_OWN_DATA_SOURCES = 'canOwnDataSources',
  CAN_OWN_APPLICATIONS = 'canOwnApplications',
}

export enum AccountActivationStatus {
  PendingActivation = 'pendingActivation',
  PendingReSign = 'pendingReSign',
  Activated = 'activated',
  Deactivated = 'deactivated',
  PendingReOnboarding = 'pendingReOnboarding',
}

export type LastActivationStatusChangeMetadata = {
  actingUserEmail: string;
  changeDate: string;
  changedFrom: AccountActivationStatus;
};

export type AccountPrivilegesMap = Partial<Record<AccountPrivileges, boolean>>;

export const INACTIVE_ACCOUNT_STATUSES = Object.freeze([
  AccountActivationStatus.PendingActivation,
  AccountActivationStatus.Deactivated,
]);
