import { ActivationModalTexts } from '@/common';
import { AddApplicationModeSelector } from '@/components/account-activation-dialog/marketplace-settings/AddApplicationModeSelector';
import { MarketplaceSettingsHeader } from '@/components/account-activation-dialog/marketplace-settings/MarketplaceSettingsHeader';
import { AdvanceSettingsToggle } from '@/components/account-activation-dialog/side-effects-dialog/AdvancedSettingsToggle';
import { AccountConfig } from '@/types/account';
import { Typography } from '@mui/material';
import { useEffect, useMemo, useState } from 'react';
import styled from 'styled-components';
import { useAccountFlowStepContext } from '../hooks/useAccountFlowStepContext';
import { stepViewedEvent } from '../shared';
import { StepSubmissionForm } from '../shared/components/StepSubmissionForm';

export interface AccountSettingsProps {
  initialAccountConfig: {
    enableSeamlessAutoApprove: boolean;
    enableAutoCreatePotentialUsers: boolean;
    marketplaceSettings: NonNullable<AccountConfig['marketplaceSettings']>;
  };
}

export const AccountSettings: React.FC<AccountSettingsProps> = ({ initialAccountConfig }) => {
  const [settings, setSettings] =
    useState<AccountSettingsProps['initialAccountConfig']>(initialAccountConfig);

  const { setCanSubmit, trackAccountFlowEvent } = useAccountFlowStepContext();

  const stepDataAnalytics = useMemo(() => {
    const { addApplicationMode } = settings.marketplaceSettings;
    const marketplaceSettingsAnalytics = {
      addApplicationMode:
        addApplicationMode === 'direct_add'
          ? 'users_directly_add_applications'
          : 'users_request_to_add_applications',
    };
    return { ...settings, marketplaceSettings: marketplaceSettingsAnalytics };
  }, [settings]);

  useEffect(() => {
    setCanSubmit(true);
    trackAccountFlowEvent(stepViewedEvent, {
      step_details: [stepDataAnalytics],
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <AccountSettingsWrapper data-testid="account-settings-container">
      {/* Step submission form */}
      <StepSubmissionForm formData={settings} analyticsData={[stepDataAnalytics]} />
      <AccountSettingsSubHeader data-testid="account-settings-sub-header">
        User Management
      </AccountSettingsSubHeader>
      <AdvanceSettingsWrapper>
        <AdvanceSettingsToggle
          isChecked={settings.enableSeamlessAutoApprove}
          onChange={(isChecked) =>
            setSettings({ ...settings, enableSeamlessAutoApprove: isChecked })
          }
          title={ActivationModalTexts.AutoApproveSeamlessToggleTitle}
          content={
            <Typography data-testid="auto-approve-seamless-toggle-description">
              {ActivationModalTexts.AutoApproveSeamlessToggleDescription1}
              <Typography>
                <SeamlessAutoApproveToggleNote>
                  <b style={{ marginTop: '3px' }}>Note:</b>{' '}
                  {ActivationModalTexts.AutoApproveSeamlessToggleDescription2}
                </SeamlessAutoApproveToggleNote>
              </Typography>
            </Typography>
          }
          switchDataAttributeValue="auto-approve-seamless-toggle"
        />

        <AdvanceSettingsToggle
          isChecked={settings.enableAutoCreatePotentialUsers}
          onChange={(isChecked) =>
            setSettings({ ...settings, enableAutoCreatePotentialUsers: isChecked })
          }
          title={ActivationModalTexts.AutoCreatePotentialUsersToggleTitle}
          content={
            <Typography data-testid="auto-create-potential-users-toggle-description">
              {ActivationModalTexts.AutoCreatePotentialUsersToggleDescription}
            </Typography>
          }
          switchDataAttributeValue="auto-create-potential-users-toggle"
        />
        <div className="h-full" data-testid="marketplace-settings-container">
          <MarketplaceSettingsHeader />
          <AddApplicationModeSelector
            disabled={false}
            selected={settings.marketplaceSettings?.addApplicationMode}
            onSelectionChange={(addApplicationMode) =>
              setSettings({
                ...settings,
                marketplaceSettings: { ...settings.marketplaceSettings, addApplicationMode },
              })
            }
          />
        </div>
      </AdvanceSettingsWrapper>
    </AccountSettingsWrapper>
  );
};

const AccountSettingsWrapper = styled.div`
  height: 100%;
  gap: 24px;
  padding-left: 30px;
  overflow-y: auto;
  padding-bottom: 20px;
`;

const AccountSettingsSubHeader = styled.span`
  font-weight: 700;
  font-size: 16px;
`;

const AdvanceSettingsWrapper = styled.div`
  margin-top: 15px;
  width: 95%;
  display: flex;
  flex-direction: column;
  letter-spacing: 0.2px;
`;

const SeamlessAutoApproveToggleNote = styled.span`
  margin-top: 2px;
  font-size: 12px;
`;
