import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { Input, AccountConfig } from '../../types';

export interface UpdateAccountConfigInput {
  accountId: number;
  config: AccountConfig;
}

export interface UpdateAccountConfigResponse {
  updateAccountConfig: { success?: boolean };
}

export const updateAccountConfigMutation = gql`
  mutation UpdateAccountConfig($input: UpdateAccountConfigInput!) {
    updateAccountConfig(input: $input) {
      success
    }
  }
`;

export function useUpdateAccountConfigMutation(
  options?: MutationHookOptions<UpdateAccountConfigResponse, Input<UpdateAccountConfigInput>>,
) {
  return useMutation(updateAccountConfigMutation, options);
}
