import { gql } from '@apollo/client';
import { GqlClientQueryOptions, gqlClientQuery } from '../../common/gqlClient';
import { FlatUser } from '../../types';

export interface GetUserByEmailQueryResult {
  getUserByEmail: FlatUser;
}

export interface GetUserByEmailVariables {
  email: string;
}

const getUserByEmailQuery = gql`
  query getUserByEmail($email: String!) {
    getUserByEmail(email: $email) {
      externalId
      email
      products
      npi
      tin
      title
      roles
      address {
        addressLine1
        addressLine2
        city
        state
        zip
        fullAddress
      }
      firstName
      lastName
      linkedEhrUser
      tag
      externalRoles
      accountId
      organizationId
      phoneNumber
    }
  }
`;

export const getUserByEmail = async (email: string, options?: GqlClientQueryOptions) => {
  const result = await gqlClientQuery<GetUserByEmailQueryResult, GetUserByEmailVariables>(
    getUserByEmailQuery,
    {
      email,
    },
    options,
  );

  return result?.getUserByEmail;
};
