import { gql, MutationHookOptions, useMutation } from '@apollo/client';

export interface CreateAppLaunchVariables {
  input?: CreateAppLaunchInput;
}

export interface CreateAppLaunchInput {
  appId: string;
  version: string;
  tokenEndpoint: string;
  organizationId?: number;
}
export interface CreateAppLaunchResponse {
  createAppLaunch: {
    launchId: string;
  };
}

const createConsoleUserMutation = gql`
  mutation createAppLaunch($input: CreateAppLaunchInput!) {
    createAppLaunch(input: $input) {
      launchId
    }
  }
`;

export function useCreateAppLaunchMutation(
  options?: MutationHookOptions<CreateAppLaunchResponse, CreateAppLaunchVariables>,
) {
  return useMutation(createConsoleUserMutation, options);
}
