import * as React from 'react';
import * as SwitchPrimitives from '@radix-ui/react-switch';
import { cn } from '../../../lib/utils';
import { VariantProps, cva } from 'class-variance-authority';
import './Switch.less';

const switchVariants = cva('', {
  variants: {
    rootVariant: {
      green: 'bg-green-1',
    },
    thumbVariant: {
      white: 'bg-white',
    },
  },
});

const handleClick = (event) => {
  event.stopPropagation();
};

const Switch = React.forwardRef<
  React.ElementRef<typeof SwitchPrimitives.Root>,
  React.ComponentPropsWithoutRef<typeof SwitchPrimitives.Root> & {
    label?: string;
    labelClassName?: string;
    stopPropagation?: boolean;
  } & VariantProps<typeof switchVariants>
>(
  (
    {
      labelClassName,
      className,
      rootVariant,
      thumbVariant,
      label,
      stopPropagation = false,
      id,
      ...props
    },
    ref,
  ) => (
    <div onClick={stopPropagation ? handleClick : undefined}>
      <SwitchPrimitives.Root
        className={cn(
          'atomic-radix-switch peer inline-flex h-5 w-9 shrink-0 cursor-pointer items-center rounded-full border-2 border-transparent transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:cursor-not-allowed disabled:opacity-50 data-[state=unchecked]:bg-gray-8',
          switchVariants({ rootVariant, className }),
          className,
        )}
        {...props}
        ref={ref}
        id={id}
      >
        <SwitchPrimitives.Thumb
          className={cn(
            'switch-handle block h-4 w-4 rounded-full bg-background shadow-lg ring-0 transition-transform data-[state=checked]:translate-x-4 data-[state=unchecked]:translate-x-0 data-[state=checked]:pointer-events-none hover:drop-shadow-xl',
            switchVariants({ thumbVariant }),
          )}
        />
      </SwitchPrimitives.Root>
      <label className={labelClassName ? labelClassName : 'switch-label text-xs pl-2'} htmlFor={id}>
        {label}
      </label>
    </div>
  ),
);
Switch.displayName = SwitchPrimitives.Root.displayName;

export { Switch };
