import { isEmail } from '@/common';
import { Input, Row } from '@/components/common';
import React, { useEffect, useState } from 'react';
import styled from 'styled-components';

interface CDESettingsProps {
  cdeContactEmail: string;
  setCdeEmail: (email: string) => void;
  setCanSubmit: (canSubmit: boolean) => void;
}
export const CDESettings: React.FC<CDESettingsProps> = ({
  cdeContactEmail,
  setCdeEmail,
  setCanSubmit,
}) => {
  const [error, setError] = useState('');

  useEffect(() => {
    const isValidEmail = isEmail(cdeContactEmail);
    setCanSubmit(isValidEmail);
    setError(isValidEmail ? '' : 'Invalid email address');
  }, [cdeContactEmail, setCanSubmit]);

  return (
    <FormSection>
      <Heading data-testid="cde-settings-heading">CDE communication email</Heading>
      <Description data-testid="cde-settings-description">
        Vim may share notifications, updates, and information related to Clinical Data Exchange.
        <br />
        We will use the email provided below to send you these updates.
      </Description>

      <InputGroup>
        <Label htmlFor="email" data-testid="cde-email-label">
          Email <Required>*</Required>
        </Label>
        <Row>
          <Input
            data-testid="cde-email-input"
            type="email"
            placeholder="bugs.bunny@acme.com"
            required
            defaultValue={cdeContactEmail}
            onChange={(e) => setCdeEmail(e.target.value)}
            error={error}
          />
        </Row>
      </InputGroup>
    </FormSection>
  );
};

const FormSection = styled.div`
  margin-top: 10px;
`;

const Heading = styled.h3`
  font-size: 16px;
  font-weight: 600;
  margin: 0;
`;

const Description = styled.p`
  font-size: 12px;
  font-weight: 400;
  color: #555;
  margin: 0;
  margin-bottom: 20px;
  line-height: 1.4;
`;

const InputGroup = styled.div`
  margin-top: 15px;
  position: relative;
`;

const Label = styled.label`
  position: absolute;
  left: 15px;
  top: -10px;
  font-size: 12px;
  background-color: white;
  padding: 0 5px;
  font-weight: 500;
`;

const Required = styled.span`
  color: #ff3333;
  margin-left: 2px;
`;
