import ReactTooltip from 'react-tooltip';
import styled from 'styled-components';
import { isNumber } from 'lodash-es';

export const Tooltip = styled((props) => (
  <ReactTooltip
    delayHide={200}
    effect="solid"
    type="light"
    arrowColor="transparent"
    place="bottom"
    delayShow={500}
    overridePosition={(position, _, currentTarget: any) => {
      const { left: targetLeft, top: targetTop } = currentTarget?.getBoundingClientRect?.() || {};
      return isNumber(targetLeft) && isNumber(targetTop)
        ? { left: targetLeft + 10, top: targetTop + 10 }
        : position;
    }}
    {...props}
  />
))`
  box-shadow: 0 5px 20px 0 ${({ theme }) => theme.colors.darkShadow};

  &.__react_component_tooltip {
    font-size: ${({ theme }) => theme.fontSizes.small};
    border-radius: ${({ theme }) => theme.borderRadius};
    padding: 3px 10px;
  }
`;
