import { QueryHookOptions, gql, useLazyQuery } from '@apollo/client';
import { FlatUser } from '../../types';

export interface GetUsersByAccountIdQueryResult {
  getUsersByAccountId: { users: FlatUser[] };
}

export interface GetUsersByAccountIdVariables {
  accountId: number;
}

const getUsersByAccountIdQuery = gql`
  query GetUsersByAccountId($accountId: Int!) {
    getUsersByAccountId(accountId: $accountId) {
      users {
        externalId
        email
        products
        firstName
        lastName
        organizationId
        roles
      }
    }
  }
`;

export function useGetUsersByAccountIdQuery(
  options?: QueryHookOptions<GetUsersByAccountIdQueryResult, GetUsersByAccountIdVariables>,
) {
  return useLazyQuery(getUsersByAccountIdQuery, options);
}
