import { createContext, useContext, useState, useCallback } from 'react';
import { isEmpty } from 'lodash-es';
import { useToast } from '../toast';
import { DataSource, ToastStatus } from '../../types';
import { useFindAllDataSourcesLazyQuery } from '../../api';

interface AllDataConnectionsContextData {
  dataConnectionsList: DataSource[];
  isLoadingDataConnectionsList: boolean;
  getDataConnectionsListError: Error | undefined;
  wasGetAllDataConnectionsCalled: boolean;
  fetchDataConnectionsList: () => void;
  clearDataConnectionsList: () => void;
}

export const DataConnectionsListContext = createContext<AllDataConnectionsContextData>({
  dataConnectionsList: [],
  isLoadingDataConnectionsList: false,
  getDataConnectionsListError: undefined,
  wasGetAllDataConnectionsCalled: false,
  fetchDataConnectionsList: () => {},
  clearDataConnectionsList: () => {},
});

export const DataConnectionsListProvider = ({ children }) => {
  const context = useDataConnectionsListContextProvider();

  const { Provider } = DataConnectionsListContext;
  return <Provider value={context}>{children}</Provider>;
};

export const useDataConnectionsListContext = (): AllDataConnectionsContextData => {
  return useContext(DataConnectionsListContext);
};

export const useDataConnectionsListContextProvider = (): AllDataConnectionsContextData => {
  const [toast] = useToast();

  const [dataConnectionsList, setDataConnectionsList] = useState<DataSource[]>([]);
  const [isLoadingAllDataConnections, setIsLoadingAllDataConnections] = useState(false);

  const [
    getAllDataConnections,
    { error: getDataConnectionsListError, called: wasGetAllDataConnectionsCalled },
  ] = useFindAllDataSourcesLazyQuery({
    fetchPolicy: 'no-cache',
    onCompleted(findAllDataSourcesResult) {
      if (!isEmpty(findAllDataSourcesResult)) {
        const dataSources = findAllDataSourcesResult?.findAllDataSources?.dataSources || [];

        setDataConnectionsList(dataSources);
        setIsLoadingAllDataConnections(false);
      }
    },
    onError() {
      setIsLoadingAllDataConnections(false);
      toast({
        status: ToastStatus.error,
        text: 'Error occurred while getting all data connections',
      });
    },
  });

  const clearDataConnectionsList = useCallback(() => {
    setIsLoadingAllDataConnections(false);
    setDataConnectionsList([]);
  }, []);

  const fetchDataConnectionsList = useCallback(() => {
    setIsLoadingAllDataConnections(true);
    getAllDataConnections();
  }, [getAllDataConnections]);

  return {
    isLoadingDataConnectionsList: isLoadingAllDataConnections,
    getDataConnectionsListError,
    dataConnectionsList,
    wasGetAllDataConnectionsCalled,
    fetchDataConnectionsList,
    clearDataConnectionsList,
  };
};
