import { createContext, FC, PropsWithChildren, useContext, useMemo } from 'react';
import { ConsoleAnalyticsClient } from '../../analytics/consoleAnalyticsClient';
import { VimConnectAnalytics } from '@getvim/vim-connect-analytics';

type BaseAnalyticsClient = Pick<
  ConsoleAnalyticsClient,
  'track' | 'identify' | 'clearSessions' | 'setBaseProperties' | 'setSession' | 'getBaseProperties'
> & { handleLogout: VimConnectAnalytics['handleLogout'] | ConsoleAnalyticsClient['handleLogout'] }; // void vs promise<void>

/** using a dummy analytics client until FF is loading ,can remove useMemo and this mock once we remove the flag and move to console user profiles */
const mockAnalyticsClient = {
  track() {
    return Promise.resolve();
  },
  identify() {
    return Promise.resolve();
  },
  setBaseProperties() {},
  getBaseProperties() {
    return {};
  },
  setSession() {},
  clearSessions() {},
  handleLogout() {
    return Promise.resolve();
  },
};

export const AnalyticsContext = createContext<BaseAnalyticsClient>(mockAnalyticsClient);

export const AnalyticsProvider: FC<PropsWithChildren<unknown>> = ({ children }) => {
  const analyticsClient: BaseAnalyticsClient = useMemo(() => {
    return new ConsoleAnalyticsClient();
  }, []);

  return <AnalyticsContext.Provider value={analyticsClient}>{children}</AnalyticsContext.Provider>;
};

export const useAnalytics = (): BaseAnalyticsClient => {
  return useContext(AnalyticsContext);
};
