import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { Input, SuccessResponse } from '../../types';

export interface UpdateUserEmailMutation {
  updateUserEmail: SuccessResponse;
}

export interface UpdateUserEmail {
  externalId: string;
  email?: string | null;
}

const updateUserEmailMutation = gql`
  mutation updateUserEmail($input: UpdateUserEmailInput!) {
    updateUserEmail(input: $input) {
      success
    }
  }
`;

export function useUpdateUserEmail(
  options?: MutationHookOptions<UpdateUserEmailMutation, Input<UpdateUserEmail>>,
) {
  return useMutation(updateUserEmailMutation, options);
}
