import React, { createContext, FC, PropsWithChildren, useCallback, useContext } from 'react';
import useLocalStorage from 'react-localstorage-hook';
import {
  DEFAULT_MAXIMUM_AMOUNT_TO_SHOW,
  Key,
  NewFeaturesOptions,
  NewFeatures as NewFeaturesType,
} from '../../types';
import { useUserContext } from '.';
import { didDayPass, getNewFeatureLocalStorageKey } from '../../common';

const NewFeaturesDefaults: NewFeaturesType = {
  [NewFeaturesOptions.POTENTIAL_USERS_MENU]: { timesShown: 0 },
  [NewFeaturesOptions.POTENTIAL_USERS_AUTO_CREATE]: { timesShown: 0 },
  [NewFeaturesOptions.CONSOLE_USERS_PAGE]: { timesShown: 0 },
  [NewFeaturesOptions.NEW_APPLICATIONS_PAGE]: { timesShown: 0 },
};

interface NewFeaturesContextData {
  shouldShowNewFeature: (
    feature: NewFeaturesOptions,
    maxAmountToShow?: number,
    disable?: boolean,
  ) => boolean;
  showedNewFeature: (feature: NewFeaturesOptions) => void;
}

export const NewFeaturesContext = createContext<NewFeaturesContextData>(
  {} as NewFeaturesContextData,
);

export const NewFeaturesProvider: FC<PropsWithChildren<unknown>> = ({ children }) => {
  const context = useNewFeatureContextProvider();
  const { Provider } = NewFeaturesContext;
  return <Provider value={context}>{children}</Provider>;
};

export const useNewFeaturesContext = (): NewFeaturesContextData => {
  return useContext(NewFeaturesContext);
};

export const useNewFeatureContextProvider = (): NewFeaturesContextData => {
  const [newFeatures, setNewFeatures] = useLocalStorage(Key.NEW_FEATURES, NewFeaturesDefaults);
  const { user } = useUserContext();

  const getLocalStorageKey = useCallback(
    (feature: NewFeaturesOptions): string | undefined => {
      return getNewFeatureLocalStorageKey(feature, user);
    },
    [user],
  );

  const showedNewFeature = useCallback(
    (feature: NewFeaturesOptions) => {
      const localStorageKey = getLocalStorageKey(feature);
      if (!localStorageKey) return;
      const featureCount = newFeatures[localStorageKey]?.timesShown || 0;
      setNewFeatures({
        ...newFeatures,
        [localStorageKey]: {
          ...newFeatures[localStorageKey],
          timesShown: featureCount + 1,
          lastDateShown: new Date(),
        },
      });
    },
    [getLocalStorageKey, newFeatures, setNewFeatures],
  );

  const shouldShowNewFeature = useCallback(
    (
      feature: NewFeaturesOptions,
      maxAmountToShow = DEFAULT_MAXIMUM_AMOUNT_TO_SHOW,
      disable?: boolean,
    ): boolean => {
      if (disable) {
        return false;
      }
      const localStorageKey = getLocalStorageKey(feature);
      if (!localStorageKey) return false;

      const shouldShow =
        !(localStorageKey in newFeatures) ||
        ((newFeatures[localStorageKey].timesShown || 0) < maxAmountToShow &&
          (!newFeatures[localStorageKey].lastDateShown ||
            didDayPass(new Date(), new Date(newFeatures[localStorageKey].lastDateShown))));

      return shouldShow;
    },
    [getLocalStorageKey, newFeatures],
  );

  return {
    shouldShowNewFeature,
    showedNewFeature,
  };
};
