import { createContext, useContext, useState, useEffect, useCallback, useMemo } from 'react';
import { isEmpty } from 'lodash-es';
import { useToast } from '../toast';
import {
  Organization,
  OrganizationTag,
  PERMISSION,
  ToastStatus,
  OrganizationRelationTypeV2,
} from '../../types';
import { findAllConsoleUserOrganizationsBatches } from '../../api';
import { authManager } from '../../common';
import { useUserContext } from './user-provider';
import { useLogger } from './LoggerProvider';
import { useAccountsListContext } from './accounts-list-provider/AccountsListProvider';
import { useCalcDsConsumingOrgs } from './useCalcDsConsumingOrgs';
import { useCalcAppConsumingOrgs } from './useCalcConsumingOrgs';

interface AllOrganizationContextData {
  organizationsList: Organization[];
  dsConsumingOrganizationsList: Organization[];
  appConsumingOrganizationsList: Organization[];
  allOrganizationsList: Organization[];
  organizationsListWithTest: Organization[];
  isLoadingOrganizationsList: boolean;
  getOrganizationsListError: Error | undefined;
  wasGetAllOrganizationsCalled: boolean;
  fetchOrganizationsList: () => void;
  clearOrganizationsList: () => void;
  isLoadingFetchOrganizationsDeps: boolean;
  ownedOrgsList: Organization[];
}

export const OrganizationsListContext = createContext<AllOrganizationContextData>({
  organizationsList: [],
  dsConsumingOrganizationsList: [],
  appConsumingOrganizationsList: [],
  allOrganizationsList: [],
  organizationsListWithTest: [],
  isLoadingOrganizationsList: false,
  getOrganizationsListError: undefined,
  wasGetAllOrganizationsCalled: false,
  fetchOrganizationsList: () => {},
  clearOrganizationsList: () => {},
  isLoadingFetchOrganizationsDeps: false,
  ownedOrgsList: [],
});

export const OrganizationListProvider = ({ children }) => {
  const context = useOrganizationsListContextProvider();

  const { Provider } = OrganizationsListContext;
  return <Provider value={context}>{children}</Provider>;
};

export const useOrganizationsListContext = (): AllOrganizationContextData => {
  return useContext(OrganizationsListContext);
};

export const useOrganizationsListContextProvider = (): AllOrganizationContextData => {
  const logger = useLogger({ scope: 'OrganizationsListContextProvider' });

  const [toast] = useToast();
  const { accountsList } = useAccountsListContext();
  const { user } = useUserContext();
  const [userAccount, setUserAccount] = useState(
    accountsList?.find((account) => account.id === user?.accountId),
  );
  const [organizationsListLoading, setOrganizationsListLoading] = useState(false);
  const [getOrganizationsListError, setGetOrganizationsListError] = useState<Error | undefined>(
    undefined,
  );
  const [fetchOrganizationsListCalled, setFetchOrganizationsListCalled] = useState(false);

  const [organizationsList, setOrganizationsList] = useState<Organization[]>([]);
  const [organizationsListWithTest, setOrganizationsListWithTest] = useState<Organization[]>([]);

  useEffect(() => {
    if (!isEmpty(accountsList) && !!user)
      setUserAccount(accountsList?.find((account) => account.id === user?.accountId));
  }, [accountsList, user]);

  const clearOrganizationsList = useCallback(() => {
    setOrganizationsList([]);
    setOrganizationsListLoading(false);
  }, []);

  const isLoadingFetchOrganizationsDeps = useMemo(() => {
    const hasAccountReadPermission = authManager.hasPermission(PERMISSION.ACCOUNT_LIST_READ);
    const accountsListDataLoading = hasAccountReadPermission && isEmpty(accountsList);
    const isVimAdmin = authManager.isVimAdmin();
    const userAccountDataLoading = !isVimAdmin && !isEmpty(accountsList) && !userAccount;
    const accountsDataLoading = accountsListDataLoading || userAccountDataLoading;
    if (accountsDataLoading || userAccountDataLoading) {
      logger.debug('accountsDataLoading', {
        accountsListDataLoading,
        userAccountDataLoading,
        hasAccountReadPermission,
        isVimAdmin,
        userAccount,
        accountsList,
      });
    }
    return accountsDataLoading;
  }, [userAccount, accountsList, logger]);

  const fetchOrganizationsList = useCallback(async () => {
    if (isLoadingFetchOrganizationsDeps) return;

    setOrganizationsListLoading(true);

    try {
      setFetchOrganizationsListCalled(true);
      const allOrgs = await findAllConsoleUserOrganizationsBatches();

      const sortedOrganizationList = sortAndFilterList(allOrgs);
      const sortedOrganizationListWithTest = sortAndFilterList(allOrgs, [OrganizationTag.VimTest]);

      setOrganizationsList(sortedOrganizationList);
      setOrganizationsListWithTest(sortedOrganizationListWithTest);
      setOrganizationsListLoading(false);
    } catch (error) {
      setGetOrganizationsListError(error as Error);
      logger.error(
        'findAllConsoleUserOrganizationsBatches',
        {
          userAccount: {
            dataSourceId: userAccount?.dataSource?.id,
            privileges: userAccount?.privileges,
            id: userAccount?.id,
            name: userAccount?.name,
          },
        },
        error as Error,
      );
      setOrganizationsListLoading(false);
      toast({
        status: ToastStatus.error,
        text: 'Error occurred while getting all organizations',
      });
    }
    return;
  }, [
    isLoadingFetchOrganizationsDeps,
    userAccount?.dataSource?.id,
    userAccount?.privileges,
    userAccount?.id,
    userAccount?.name,
    logger,
    toast,
  ]);

  const ownedOrDsConsumingOrgs = useMemo(() => {
    return organizationsList.filter((o) => {
      return (
        (o as Organization).relationTypes?.includes(OrganizationRelationTypeV2.Owned) ||
        (o as Organization).relationTypes?.includes(OrganizationRelationTypeV2.DataConsuming)
      );
    });
  }, [organizationsList]);

  const ownedOrgsList = useMemo(() => {
    return organizationsList.filter((o) => {
      return o.relationTypes?.includes(OrganizationRelationTypeV2.Owned);
    });
  }, [organizationsList]);

  const appConsumingOrgs = useCalcAppConsumingOrgs(organizationsList);

  const dsConsumingOrgs = useCalcDsConsumingOrgs(organizationsList);

  return {
    isLoadingOrganizationsList: organizationsListLoading,
    getOrganizationsListError: getOrganizationsListError,
    organizationsList: ownedOrDsConsumingOrgs,
    dsConsumingOrganizationsList: dsConsumingOrgs,
    appConsumingOrganizationsList: appConsumingOrgs,
    allOrganizationsList: organizationsList,
    organizationsListWithTest,
    wasGetAllOrganizationsCalled: fetchOrganizationsListCalled,
    fetchOrganizationsList,
    clearOrganizationsList,
    isLoadingFetchOrganizationsDeps,
    ownedOrgsList,
  };
};

const sortAndFilterList = (
  organizationsList: Organization[],
  listFilter: OrganizationTag[] = [OrganizationTag.VimTest, OrganizationTag.AppTest],
) => {
  if (!organizationsList) {
    return [];
  }

  const filteredOrganizationList = !authManager.isVimAdmin()
    ? organizationsList.filter(
        (organization) => !organization.tag || !listFilter.includes(organization.tag),
      )
    : organizationsList;

  const sortedOrganizations = filteredOrganizationList.sort((first, second) =>
    first.name.toLowerCase().localeCompare(second.name.toLowerCase()),
  );

  return sortedOrganizations;
};
