import { gql, MutationHookOptions, useMutation } from '@apollo/client';

export interface UpdateOrganizationByOrgAdminInput {
  id: number;
  isSeamlessLoginAutoApproved?: boolean;
  shouldAutoCreatePotentialUsers?: boolean;
}

export interface UpdateOrganizationByOrgAdminMutation {
  updateOrganizationByOrgAdmin?: UpdateOrganizationByOrgAdminInput;
}

export interface UpdateOrganizationByOrgAdminArgs {
  input: UpdateOrganizationByOrgAdminInput;
}

export const updateOrganizationByOrgAdminMutation = gql`
  mutation updateOrganizationByOrgAdmin($input: UpdateOrganizationByOrgAdminInput!) {
    updateOrganizationByOrgAdmin(input: $input) {
      id
      isSeamlessLoginAutoApproved
      shouldAutoCreatePotentialUsers
    }
  }
`;

export function useUpdateOrganizationByOrgAdminMutation(
  options?: MutationHookOptions<
    UpdateOrganizationByOrgAdminMutation,
    UpdateOrganizationByOrgAdminArgs
  >,
) {
  return useMutation(updateOrganizationByOrgAdminMutation, options);
}
