import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { AccountPrivileges, AccountRelation } from '../../types';

export interface UpdateAccountInput {
  accountId: number;
  managedBy?: number | null;
  privileges?: AccountPrivileges[];
  relations?: AccountRelation[];
}

export interface UpdateAccountMutation {
  success?: boolean;
}

export interface UpdateAccountArgs {
  input: UpdateAccountInput;
}

export const updateAccountMutation = gql`
  mutation UpdateAccount($input: UpdateAccountInput!) {
    updateAccount(input: $input) {
      success
    }
  }
`;

export function useUpdateAccountMutation(
  options?: MutationHookOptions<UpdateAccountMutation, UpdateAccountArgs>,
) {
  return useMutation(updateAccountMutation, options);
}
