import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { PotentialUserMetadata } from '../../types';

export interface UpdatePotentialUserMutation {
  updatePotentialUser: Omit<PotentialUserMetadata, 'isVerified'>;
}

export type UpdatePotentialUserMetadataInput = Omit<
  PotentialUserMetadata,
  'organizationId' | 'updatedAt' | 'createdAt' | 'linkedEhrUser' | 'isVerified'
>;

export interface UpdatePotentialUserMetadataVariables {
  input: UpdatePotentialUserMetadataInput;
}

const updatePotentialUserMutation = gql`
  mutation updatePotentialUser($input: UpdatePotentialUserMetadataInput!) {
    updatePotentialUser(input: $input) {
      id
      organizationId
      linkedEhrUser
      createdAt
      npi
      tin
      address {
        addressLine1
        addressLine2
        city
        state
        zip
      }
      firstName
      lastName
      email
      phoneNumber
      isDismissed
      updatedAt
    }
  }
`;

export function useUpdatePotentialUserMutation(
  options?: MutationHookOptions<UpdatePotentialUserMutation, UpdatePotentialUserMetadataVariables>,
) {
  return useMutation(updatePotentialUserMutation, options);
}
