import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { VimAdmin } from '../../types';

export interface CreateAdminVariables {
  input?: CreateAdminInput;
}

export interface CreateAdminInput {
  email: string;
}

export interface CreateAdminResult {
  success?: boolean;
}

export interface CreateAdminResult {
  createAdmin: VimAdmin;
}

export const createAdminMutation = gql`
  mutation createAdmin($input: CreateAdminInput!) {
    createAdmin(input: $input) {
      id
      email
    }
  }
`;

export function useCreateAdminMutation(
  options?: MutationHookOptions<CreateAdminResult, CreateAdminVariables>,
) {
  return useMutation(createAdminMutation, options);
}
