import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { Input } from '../../types';

export interface ActivateAccountInput {
  accountId: number;
}

export interface ActivateAccountResponse {
  activateAccount: { success?: boolean };
}

export const activateAccountMutation = gql`
  mutation ActivateAccount($input: ActivateAccountInput!) {
    activateAccount(input: $input) {
      success
    }
  }
`;

export function useActivateAccountMutation(
  options?: MutationHookOptions<ActivateAccountResponse, Input<ActivateAccountInput>>,
) {
  return useMutation(activateAccountMutation, options);
}
