import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { Input, Organization } from '../../types';

export interface UpdateProviderOrganizationInput {
  accountId: number;
  id: number;
  isOptOutFromVC: boolean;
}

export interface UpdateProviderOrganizationMutationResponse {
  updateProviderOrganization?: Organization;
}

export const updateProviderOrganizationMutation = gql`
  mutation UpdateProviderOrganization($input: UpdateProviderOrganizationInput!) {
    updateProviderOrganization(input: $input) {
      id
      name
      ehrSystem
      ehrUrl
      products {
        name
        displayName
        sources
        providerSources
        contentSources
      }
      namespaceName
      identityProvider
      tag
      accountId
      ehrIdentifier
      isOptOutFromVC
    }
  }
`;

export function useUpdateProviderOrganizationMutation(
  options?: MutationHookOptions<
    UpdateProviderOrganizationMutationResponse,
    Input<UpdateProviderOrganizationInput>
  >,
) {
  return useMutation(updateProviderOrganizationMutation, options);
}
