import { ToastContentProps } from 'react-toastify';
import styled from 'styled-components';
import { Column, IconButton, Row } from '../common';
import errorIcon from '../../assets/icons/toast-error.png';
import successIcon from '../../assets/icons/toast-success.png';
import { ToastStatus, UseToastFunctionParameters } from '../../types';

const icons = {
  [ToastStatus.success]: successIcon,
  [ToastStatus.error]: errorIcon,
};

const defaultTitles = {
  [ToastStatus.success]: 'Success!',
  [ToastStatus.error]: 'Error!',
};

const defaultTexts = {
  [ToastStatus.success]: 'Action completed successfully',
  [ToastStatus.error]: 'Something went wrong',
};

declare type Props = ToastContentProps & UseToastFunctionParameters;

export const Toast = ({ status, title, text, closeToast }: Props) => (
  <Container alignItems="center">
    <Icon src={icons[status]} alt="" />
    <Column>
      <Title>{title ?? defaultTitles[status]}</Title>
      <Text>{text ?? defaultTexts[status]}</Text>
    </Column>
    <XButton fontIconName="icon-x-2" onClick={() => closeToast?.()} />
  </Container>
);

const Container = styled(Row)`
  color: ${({ theme }) => theme.colors.textHeading};
  padding: 15px 20px;
`;

const Icon = styled.img`
  width: 40px;
  height: 40px;
  margin-right: 20px;
`;

const Title = styled.div`
  font-size: ${({ theme }) => theme.fontSizes.normal};
  font-weight: bold;
`;

const Text = styled.div`
  font-size: ${({ theme }) => theme.fontSizes.small};
`;

const XButton = styled(IconButton)`
  position: absolute;
  top: 12px;
  right: 12px;
`;
