import React, { useEffect, useMemo } from 'react';
import { get, isEmpty, isObject, isString } from 'lodash-es';
import { SORT_DIRECTION } from '../../types';
import { FixedSizeList } from 'react-window';
import AutoSizer from 'react-virtualized-auto-sizer';
import { Loader } from '@getvim/atomic-ui';
import styled from 'styled-components';
import './SortableElementTable.less';

export interface SortableElementTableProps<T> {
  element: React.FC<T>;
  data: Array<T & { id: string | number; disabled?: boolean }>;
  /** Can be nested object by using 'key.innerKey' ie: 'ehrUser.firstName' */
  sortBy?: string;
  sortDirection?: SORT_DIRECTION;
  filterBy?: string;
  filterOptions?: string[];
  emptyTableView?: JSX.Element;
  itemHeight: number;
  gap?: number;
  loading?: boolean;
  onRenderedRowsChange?: (renderedRowsCount: number) => void;
}
const getSortableValue = (element: any, sortBy: string) => {
  const rawValue = get(element, sortBy);
  let sortableValue = rawValue;
  if (isString(sortableValue)) {
    sortableValue = sortableValue.toLowerCase();
  }
  if (isObject(sortableValue)) {
    sortableValue = JSON.stringify(sortableValue);
  }
  return sortableValue;
};

const sortFunction = (
  firstElement: any,
  secondElement: any,
  sortBy: string,
  sortDirection: SORT_DIRECTION,
) => {
  const sortDirectionMultiplier = sortDirection === SORT_DIRECTION.ASCENDING ? 1 : -1;
  const firstElementValue = getSortableValue(firstElement, sortBy);
  const secondElementValue = getSortableValue(secondElement, sortBy);
  if (firstElementValue < secondElementValue) {
    return -1 * sortDirectionMultiplier;
  }
  if (firstElementValue > secondElementValue) {
    return 1 * sortDirectionMultiplier;
  }
  return 0;
};

const filterFunction = (objectData: any, filterBy: string, filterOptions: string[]) => {
  const filterValues: string[] = filterOptions.map((option) => get(objectData, option));
  return filterValues.find(
    (value) => value && value?.toString().toLowerCase().includes(filterBy.toLowerCase()),
  );
};

const defaultGetItemKey = (_, item) => item.id;

export const SortableElementTable = <T,>({
  data,
  element,
  sortBy,
  sortDirection = SORT_DIRECTION.ASCENDING,
  filterBy,
  filterOptions,
  emptyTableView,
  gap = 10,
  itemHeight,
  loading,
  onRenderedRowsChange,
}: SortableElementTableProps<T>) => {
  const dataForTable = useMemo(() => {
    let clonedData = [...data];
    if (sortBy)
      clonedData = clonedData.sort((firstElement, secondElement) =>
        sortFunction(firstElement, secondElement, sortBy, sortDirection),
      );

    if (!isEmpty(filterBy) && filterOptions) {
      clonedData = clonedData.filter((singleDataObj) =>
        filterFunction(singleDataObj, filterBy!, filterOptions),
      );
    }

    return clonedData;
  }, [sortDirection, sortBy, filterBy, filterOptions, data]);

  useEffect(() => {
    if (onRenderedRowsChange) {
      onRenderedRowsChange(dataForTable.length);
    }
  }, [dataForTable, onRenderedRowsChange]);

  if (loading) {
    return <StyledLoader />;
  }

  if (isEmpty(dataForTable)) {
    return emptyTableView ?? <div>No data to show</div>;
  }

  const BaseElementToShow = element;

  const itemSize = (itemHeight || 0) + gap;

  return (
    <div style={{ height: '100%', width: '100%;' }}>
      <AutoSizer>
        {({ height, width }) => (
          <FixedSizeList
            height={height}
            width={width}
            itemCount={dataForTable.length}
            itemSize={itemSize}
            itemData={dataForTable}
            itemKey={defaultGetItemKey}
          >
            {({ index, style }) => {
              return (
                <div
                  style={{ ...style }}
                  className={(dataForTable[index].disabled && 'disabled') || ''}
                >
                  <BaseElementToShow {...dataForTable[index]!} />
                </div>
              );
            }}
          </FixedSizeList>
        )}
      </AutoSizer>
    </div>
  );
};

const StyledLoader = styled(Loader)`
  margin-top: 100px;
`;
