import { type ClassValue, clsx } from 'clsx';
import { twMerge } from 'tailwind-merge';
import { authManager } from '../../../common';
import { ApplicationVersion, ApplicationVersionStatus } from '@getvim-os/types';
import { ApplicationUIStatus } from '../../../api/applications';
import { ApplicationStatusText } from './texts';

const URL_REGEX = /^https?:\/\/[^\s#$.?].\S*$/;

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export function isValidUrl(url: string) {
  return URL_REGEX.test(url);
}

export function isValidUrls(urls: string) {
  return urls.split(',').every((url) => isValidUrl(url.trim()));
}

export const isUrlListValid = (urlList: Array<string | undefined>) => {
  if (!Array.isArray(urlList)) return false;
  return urlList.every((url: string | undefined) => {
    return isValidUrls(url || '');
  });
};

const emailRegex =
  /^(([^\s"(),.:;<>@[\\\]]+(\.[^\s"(),.:;<>@[\\\]]+)*)|.(".+"))@((\[(?:\d{1,3}\.){3}\d{1,3}])|(([\dA-Za-z\-]+\.)+[A-Za-z]{2,}))$/;
export function isValidEmail(email: string) {
  return emailRegex.test(String(email).toLowerCase());
}

const fallbackSandboxLink = 'https://sandbox-ehr.getvim.com/login?connection=vim-console-saml-idp';
export function openSandboxApp(appInfo?: { appId: string; version: string }) {
  try {
    const isAdmin: boolean = authManager.isVimAdmin();
    const link = new URL(
      isAdmin
        ? (window.$vim_environment.VIM_SANDBOX_EHR_ADMIN_LINK as string)
        : (window.$vim_environment.VIM_SANDBOX_EHR_LINK as string),
    );
    if (appInfo) {
      link.searchParams.set('appId', appInfo.appId);
      link.searchParams.set('appVersion', appInfo.version);
    }
    window.open(link.toString(), '_blank');
  } catch {
    window.open(fallbackSandboxLink, '_blank');
  }
}

export const applicationUIStatusToText: Record<ApplicationUIStatus, string> = {
  [ApplicationUIStatus.DRAFT]: ApplicationStatusText.Draft,
  [ApplicationUIStatus.IN_REVIEW]: ApplicationStatusText.InReview,
  [ApplicationUIStatus.DECLINED]: ApplicationStatusText.Declined,
  [ApplicationUIStatus.PENDING_RELEASE]: ApplicationStatusText.PendingRelease,
  [ApplicationUIStatus.LIVE]: ApplicationStatusText.Live,
};

export const versionStatusToUIStatus = (
  applicationVersion: Pick<ApplicationVersion, 'isLive' | 'status'>,
): ApplicationUIStatus => {
  if (applicationVersion.isLive) {
    return ApplicationUIStatus.LIVE;
  } else {
    switch (applicationVersion.status) {
      case ApplicationVersionStatus.DRAFT:
        return ApplicationUIStatus.DRAFT;
      case ApplicationVersionStatus.PENDING_REVIEW:
        return ApplicationUIStatus.IN_REVIEW;
      case ApplicationVersionStatus.DECLINED:
        return ApplicationUIStatus.DECLINED;
      case ApplicationVersionStatus.RELEASED:
        return ApplicationUIStatus.PENDING_RELEASE;
      default:
        return ApplicationUIStatus.DRAFT;
    }
  }
};
