import {
  ApolloQueryResult,
  gql,
  LazyQueryHookOptions,
  useApolloClient,
  useLazyQuery,
} from '@apollo/client';
import { FlatUserFragment } from '../../types';
import { FlatUserFragmentDoc } from '../users';
import { useQuery, UseQueryResult } from '@tanstack/react-query';

export interface GetOrganizationUsersQuery {
  getOrganizationUsers: FlatUserFragment[];
}

export interface GetOrganizationUsersVariables {
  organizationId: number;
}

const getOrganizationUsersQuery = gql`
  query getOrganizationUsers($organizationId: Int!) {
    getOrganizationUsers(organizationId: $organizationId) {
      ...FlatUserFragment
    }
  }
  ${FlatUserFragmentDoc}
`;

export function useGetOrganizationUsersLazyQuery(
  options?: LazyQueryHookOptions<GetOrganizationUsersQuery, GetOrganizationUsersVariables>,
) {
  return useLazyQuery(getOrganizationUsersQuery, options);
}

export const useGetOrganizationUsers = (
  organizationId?: number,
): UseQueryResult<FlatUserFragment[]> => {
  const apolloClient = useApolloClient();
  return useQuery({
    queryKey: ['getOrganizationUsers', organizationId],
    enabled: !!organizationId,
    queryFn: () =>
      apolloClient.query({
        query: getOrganizationUsersQuery,
        variables: { organizationId },
        fetchPolicy: 'no-cache',
      }),
    staleTime: 3000,
    select: (data: ApolloQueryResult<GetOrganizationUsersQuery>) => data.data?.getOrganizationUsers,
  });
};
