import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { Input, SuccessResponse } from '../../types';

export interface SendReSignEmailMutation {
  sendReSignMail: SuccessResponse;
}

export interface SendReSignEmailInput {
  id: string;
  isNewUser: boolean;
  withApology?: boolean;
}

const sendReSignEmailMutation = gql`
  mutation SendReSignMail($input: SendReSignMailInput!) {
    sendReSignMail(input: $input) {
      success
    }
  }
`;

export function useSendReSignEmailMutation(
  options?: MutationHookOptions<SendReSignEmailMutation, Input<SendReSignEmailInput>>,
) {
  return useMutation(sendReSignEmailMutation, options);
}
