import React from 'react';
import styled from 'styled-components';
import { Column } from './column';

export interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  high?: boolean;
  wide?: boolean;
  error?: string;
  onEnterPress?: () => void;
}

const onKeyDown = (
  event: React.KeyboardEvent<HTMLInputElement>,
  onEnterPress?: () => void,
): void => {
  if (!onEnterPress) {
    return;
  }
  const value = event.key || event.keyCode || event.which;
  if (value === 'Enter' || value === 13) {
    onEnterPress();
  }
};

export const Input: React.FC<InputProps> = ({ error, onEnterPress, ...props }) => (
  <InputContainer flex="0">
    <StyledInput
      error={error}
      onKeyDown={(event: React.KeyboardEvent<HTMLInputElement>) => onKeyDown(event, onEnterPress)}
      {...props}
    />
    {error && <ErrorMessage>{error}</ErrorMessage>}
  </InputContainer>
);

const InputContainer = styled(Column)`
  color: ${(props) => props.theme.colors.textHeading};
`;

const StyledInput = styled(({ error, high, wide, ...props }) => <input {...props} />)`
  width: ${({ wide }) => (wide ? '350px' : '320px')};
  height: ${({ high }) => (high ? '48px' : '36px')};
  font-size: ${(props) => props.theme.fontSizes.normal};
  color: ${(props) =>
    props.disabled
      ? props.theme.colors.greyPlaceholder
      : props.error
      ? props.theme.colors.error
      : props.theme.colors.black};
  padding: 0 10px;
  border: 1px solid
    ${(props) => (props.error ? props.theme.colors.error : props.theme.colors.textHeading)};
  border-radius: ${(props) => props.theme.borderRadius};
  box-sizing: border-box;
`;

const ErrorMessage = styled(({ high, ...props }) => <div {...props} />)`
  align-self: flex-end;
  font-size: ${(props) => props.theme.fontSizes.small};
  color: ${(props) => props.theme.colors.error};
  margin-top: 4px;
`;
