import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { AddressInput, ExternalRole, Tags } from '../../types';
import { CreateUserInput } from '../users';
import { AccountPermissions } from './accountPermissions';

export interface CreateConsoleUserVariables {
  input?: CreateConsoleUserInput;
}

export interface CreateConsoleUserInput {
  accountId: number;
  email: string;
  username?: string;
  password?: string;
  phoneNumber?: string;
  firstName?: string;
  lastName?: string;
  tag?: Tags;
  address?: AddressInput;
  vcUserMetadata?: CreateUserInput;
  permittedOrganizations: AccountPermissions;
  externalRoles?: ExternalRole[];
  npi?: string;
  tin?: string[];
}
export interface CreateConsoleUserResult {
  success?: boolean;
}

const createConsoleUserMutation = gql`
  mutation createConsoleUser($input: CreateConsoleUserInput!) {
    createConsoleUser(input: $input) {
      success
    }
  }
`;

export function useCreateConsoleUserMutation(
  options?: MutationHookOptions<CreateConsoleUserResult, CreateConsoleUserVariables>,
) {
  return useMutation(createConsoleUserMutation, options);
}
