import { LazyQueryHookOptions, gql, useLazyQuery } from '@apollo/client';

interface GetAllNamespacesQuery {
  getAllNamespaces: string[];
}

const getAllNamespacesQuery = gql`
  query GetAllNamespaces {
    getAllNamespaces
  }
`;

export function useGetAllNamespacesLazyQuery(
  options?: LazyQueryHookOptions<GetAllNamespacesQuery, null>,
) {
  return useLazyQuery(getAllNamespacesQuery, options);
}
