import { gql, LazyQueryHookOptions, useLazyQuery } from '@apollo/client';
import { Account } from '../../types';

export interface FindAccountVariables {
  accountId: number;
  omitDataSourceData?: boolean;
  omitProviderOrganizationsData?: boolean;
  includeLegalDocSignatureData?: boolean;
}

export interface FindAccountVariablesInput {
  input: FindAccountVariables;
}
export interface FindAccountQuery {
  findAccount?: Account;
}

const findAccountQuery = gql`
  query FindAccount($input: FindAccountInput!) {
    findAccount(input: $input) {
      id
      name
      address
      phoneNumber
      tin
      privileges
      managingAccountMetadata {
        id
        name
      }
      activationStatus
      isManagingOtherAccounts
      createdAt
      updatedAt
      dataSource {
        id
        accountId
        name
        dataSourceEnum
        tin
        createdAt
        updatedAt
        namespace
        type
        theme {
          logo {
            url
            height
            width
          }
          title {
            color
            backgroundColor
          }
        }
      }
      providerOrganizationIds
      applications
      relations {
        relatedAccountId
        relationType
      }
      config {
        enableSeamlessAutoApprove
        enableAutoCreatePotentialUsers
        enableCDEForOrg
        activateCDEForUsers
        marketplaceSettings
      }
      isActive
      doNotContact
      isTest
      lastActivationStatusChangeMetadata {
        changedFrom
        actingUserEmail
        changeDate
      }
      accountAuth {
        clientId
        clientSecret
      }
      tosSignatureDate
    }
  }
`;

export function useGetAccountLazyQuery(
  options?: LazyQueryHookOptions<FindAccountQuery, FindAccountVariablesInput>,
) {
  return useLazyQuery(findAccountQuery, options);
}
