import { gql, QueryHookOptions, useQuery } from '@apollo/client';
import { Application, ApplicationVersionResponse } from '../applications';
import { ApplicationVersion, ApplicationVersionSubmission } from '@getvim-os/types';

const getApplicationsAwaitingApprovalQuery = gql`
  ${ApplicationVersionResponse}
  query GetApplicationsAwaitingApproval($accountId: Int!) {
    getApplicationsAwaitingApproval(accountId: $accountId) {
      id
      version
      displayName
      iconUrl
      createdBy
      createdAt
      appStoreListing
      liveVersion {
        ...ApplicationVersionResponseFields
      }
      dataSources {
        id
        name
      }
    }
  }
`;

export interface GetApplicationsAwaitingApprovalResponse extends Application {
  appStoreListing: ApplicationVersionSubmission['appStoreListing'];
  liveVersion: ApplicationVersion;
  dataSources: { id: string; name: string }[];
}

type GetApplicationsAwaitingApprovalQuery = {
  getApplicationsAwaitingApproval: GetApplicationsAwaitingApprovalResponse[];
};

export const useGetApplicationsAwaitingApproval = (
  options: QueryHookOptions<GetApplicationsAwaitingApprovalQuery, { accountId: number }>,
) => useQuery(getApplicationsAwaitingApprovalQuery, { fetchPolicy: 'no-cache', ...options });
