import { gql, LazyQueryHookOptions, useLazyQuery } from '@apollo/client';
import { ConsoleUser, UserType } from '../../types';

export interface FindAllConsoleUsersResponse {
  findConsoleUsers: {
    users: ConsoleUser[];
  };
}

export interface FindAllConsoleUsersVariables {
  accountId?: number;
  filter?: { externalRoles?: UserType[]; withPOData?: boolean };
}

export interface FindAllConsoleUsersInput {
  input: FindAllConsoleUsersVariables;
}

const findAllConsoleUsers = gql`
  query FindConsoleUsers($input: FindConsoleUsersInput) {
    findConsoleUsers(input: $input) {
      users {
        externalId
        firstName
        lastName
        email
        externalRoles
        activatedAt
        activationSentAt
        phoneNumber
        linkedEhrUser
        accountId
        organizationId
        permittedOrganizationsMetadata {
          id
          name
          accountId
        }
      }
    }
  }
`;

export function useFindAllConsoleUsersQuery(
  options?: LazyQueryHookOptions<FindAllConsoleUsersResponse, FindAllConsoleUsersInput>,
) {
  return useLazyQuery(findAllConsoleUsers, options);
}
