/**
Based on the Apollo built in [removeTypenameFromVariables](https://www.apollographql.com/docs/react/api/link/apollo-link-remove-typename/) link,
See this original code [here](https://github.com/apollographql/apollo-client/blob/main/src/link/remove-typename/removeTypenameFromVariables.ts)
which is only available in Apollo Client 3.8.0 and above.
*/
import { ApolloLink } from '@apollo/client';
import { omitDeep } from './omitDeep';

export const removeTypenameFromVariables = (options: { operationNames: string[] }) =>
  new ApolloLink((operation, forward) => {
    const { operationName, variables } = operation;
    const { operationNames } = options;

    if (operationName && operationNames.includes(operationName) && variables) {
      operation.variables = omitDeep(variables, '__typename');
    }

    return forward(operation);
  });
