import { GenericErrorModal } from '@/common/GenericErrorModal';
import { AccountConfig, AccountFlow, AccountFlowStep, AccountFlowStepType } from '@/types';
import { Loader } from '@getvim/atomic-ui';
import { useMemo, useState } from 'react';
import styled from 'styled-components';
import { ConfirmationDialog } from '../common';
import { StepContext } from './hooks/useAccountFlowStepContext';
import { AccountFlowStepProps, cdeAppId } from './shared';
import { StepLayout } from './step-layout/StepLayout';
import {
  AccountDetails,
  AccountSettings,
  AccountSettingsProps,
  ApplicationsReview,
  ApplicationsSettings,
  DownloadMSI,
  SignTos,
} from './steps';

interface AccountFlowModalViewProps extends AccountFlowStepProps {
  flow: AccountFlow;
  userEmail?: string;
  currentStep: AccountFlowStep;
  accountConfig?: AccountConfig;
  accountApplications?: string[];
}
export const AccountFlowModalView: React.FC<AccountFlowModalViewProps> = ({
  flow,
  userEmail,
  currentStep,
  accountConfig,
  accountApplications,
  isSubmitting,
  setIsSubmitting,
  onStepSubmitted,
  trackAccountFlowEvent,
}) => {
  const stepType = currentStep.type;

  const [error, setError] = useState('');
  const [canSubmit, setCanSubmit] = useState(false);
  const [isLoadingStepData, setIsLoadingStepData] = useState(false);
  const [submitButtonText, setSubmitButtonText] = useState('Save & Continue');

  const totalSteps = useMemo(() => {
    const numberOfSteps = flow.steps.length;
    const hasCDE = accountApplications?.some((app) => app === cdeAppId);
    // We currently only support CDE settings, if CDE is not installed, we skip the applications settings step
    return hasCDE ? numberOfSteps : numberOfSteps - 1;
  }, [flow.steps, accountApplications]);

  const currentStepIndex = useMemo(
    () => flow.steps.findIndex((step) => step.type === currentStep.type),
    [flow.steps, currentStep.type],
  );

  const initialAccountConfig = useMemo((): AccountSettingsProps['initialAccountConfig'] => {
    const { marketplaceSettings } = accountConfig ?? {};

    /** We set initial value regardless of db as direct_add only for isReSignTos
     *  and when the FF shouldReSignToSAccountFlowIncludeAccountSettings is on.
     *  Remove this logic if we don't want to continue with it later, as it is considered temporary */
    const addApplicationMode =
      flow.type === 'reSignTos'
        ? 'direct_add'
        : marketplaceSettings?.addApplicationMode ?? 'direct_add';

    return {
      enableSeamlessAutoApprove: accountConfig?.enableSeamlessAutoApprove ?? true,
      enableAutoCreatePotentialUsers: accountConfig?.enableAutoCreatePotentialUsers ?? true,
      marketplaceSettings: {
        ...marketplaceSettings,
        addApplicationMode,
      },
    };
  }, [accountConfig, flow.type]);

  if (error) {
    return <GenericErrorModal />;
  }

  return (
    <ConfirmationDialog open className="modal" width="690px">
      <StepWrapper data-testid="account-flow-modal">
        <StepContext.Provider
          value={{
            accountId: flow.accountId,
            canSubmit,
            isSubmitting,
            submitButtonText,
            totalSteps,
            currentStepIndex,
            setCanSubmit,
            setIsSubmitting,
            onStepSubmitted,
            setSubmitButtonText,
            trackAccountFlowEvent,
            setIsLoadingStepData,
            setError,
          }}
        >
          {isLoadingStepData && (
            <LoadingOverlay>
              <Loader size={'default'} />
            </LoadingOverlay>
          )}

          {stepType === AccountFlowStepType.SignTos && <SignTos flowType={flow.type} />}
          {stepType === AccountFlowStepType.AccountDetails && (
            <StepLayout header="Setup account details">
              <AccountDetails />
            </StepLayout>
          )}
          {stepType === AccountFlowStepType.AccountSettings && (
            <StepLayout header="Setup account settings">
              <AccountSettings initialAccountConfig={initialAccountConfig} />
            </StepLayout>
          )}
          {stepType === AccountFlowStepType.ApplicationsReview && (
            <StepLayout header="Install applications">
              <ApplicationsReview />
            </StepLayout>
          )}
          {stepType === AccountFlowStepType.ApplicationsSettings && (
            <StepLayout header="Application settings">
              <ApplicationsSettings userEmail={userEmail} />
            </StepLayout>
          )}
          {stepType === AccountFlowStepType.DownloadMSI && (
            <StepLayout simpleFooter={true}>
              <DownloadMSI />
            </StepLayout>
          )}
        </StepContext.Provider>
      </StepWrapper>
    </ConfirmationDialog>
  );
};

const StepWrapper = styled.div`
  height: 640px;
  position: relative; /* For absolute positioning of overlay */
`;

const LoadingOverlay = styled.div`
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background-color: rgba(255, 255, 255, 1);
  z-index: 500;
`;
