import {
  gql,
  LazyQueryHookOptions,
  QueryHookOptions,
  useLazyQuery,
  useQuery,
} from '@apollo/client';
import { EnrichedAccount } from '../../types';

export type SlimAccount = Pick<
  EnrichedAccount,
  'id' | 'name' | 'providerOrganizationIds' | 'dataSource'
>;
export interface FindAllAccountsQuery {
  findAllAccounts: EnrichedAccount[];
}

export interface FindAllAccountsSlimQuery {
  findAllAccounts: SlimAccount[];
}

export interface FindAllAccountsVariables {
  omitDataSourceData?: boolean;
  omitProviderOrganizationsData?: boolean;
  omitApplicationsData?: boolean;
  options?: AccountOptions[];
}
export interface FindAllAccountsVariablesInput {
  input: FindAllAccountsVariables;
}

export enum AccountOptions {
  DataSource = 'dataSource',
  ProviderOrganizations = 'providerOrganizations',
}

const findAllAccountsQuery = gql`
  query FindAllAccounts($input: FindAllAccountsInput) {
    findAllAccounts(input: $input) {
      id
      name
      address
      phoneNumber
      tin
      createdAt
      updatedAt
      dataSource {
        id
        accountId
        name
        dataSourceEnum
        tin
        createdAt
        updatedAt
        namespace
        type
        theme {
          logo {
            url
            height
            width
          }
          title {
            color
            backgroundColor
          }
        }
      }
      providerOrganizationIds
      applications
      privileges
      relations {
        relatedAccountId
        relationType
      }
      config {
        enableSeamlessAutoApprove
        enableAutoCreatePotentialUsers
        enableCDEForOrg
        activateCDEForUsers
        marketplaceSettings
      }
    }
  }
`;

const findAllAccountsSlimQuery = gql`
  query FindAllAccounts($input: FindAllAccountsInput) {
    findAllAccounts(input: $input) {
      id
      name
      providerOrganizationIds
      dataSource {
        id
        accountId
        name
        dataSourceEnum
        tin
        createdAt
        updatedAt
      }
    }
  }
`;

export function useFindAllAccountsQuery(
  options?: QueryHookOptions<FindAllAccountsQuery, FindAllAccountsVariablesInput>,
) {
  return useQuery(findAllAccountsQuery, options);
}

export function useFindAllAccountsLazyQuery(
  options?: LazyQueryHookOptions<FindAllAccountsQuery, FindAllAccountsVariablesInput>,
) {
  return useLazyQuery(findAllAccountsQuery, options);
}

export function useGetAccountsSlimQuery(
  options?: QueryHookOptions<FindAllAccountsSlimQuery, FindAllAccountsVariablesInput>,
) {
  return useQuery(findAllAccountsSlimQuery, options);
}
