import { useGetApplicationsAwaitingApproval, useUpdateAccountConfigMutation } from '@/api';
import { AccountFlowAnalyticsEvents } from '@/common';
import { useToast } from '@/components/toast';
import { ToastStatus } from '@/types';
import styled from '@emotion/styled';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useAccountFlowStepContext } from '../../hooks/useAccountFlowStepContext';
import { AppHeader, ApplicationSettings, cdeAppId, stepViewedEvent } from '../../shared';
import { CDESettings } from './CDESettings';

interface ApplicationSettingsProps {
  userEmail?: string;
}
export const ApplicationsSettings: React.FC<ApplicationSettingsProps> = ({ userEmail }) => {
  const [toast] = useToast();
  const [cdeEmail, setCdeEmail] = useState(userEmail || '');
  const [apps, setApps] = useState<ApplicationSettings[]>([]);
  const fetched = useRef(false);
  const {
    accountId,
    setError,
    setCanSubmit,
    isSubmitting,
    setIsSubmitting,
    submitButtonText,
    setSubmitButtonText,
    onStepSubmitted: submit,
    setIsLoadingStepData,
    trackAccountFlowEvent,
  } = useAccountFlowStepContext();

  const [updateAccountConfigApi] = useUpdateAccountConfigMutation();
  const { loading, error, data } = useGetApplicationsAwaitingApproval({
    variables: { accountId },
  });

  useEffect(() => {
    if (error) {
      setError(error.message);
      return;
    }

    if (loading) {
      setIsLoadingStepData(true);
      return;
    }

    if (isSubmitting) {
      return;
    }

    const applications = (data?.getApplicationsAwaitingApproval || [])
      .filter((app) => app.id === cdeAppId)
      .map((app) => ({ ...app, done: false }));

    if (fetched.current) {
      return;
    }

    if (applications.length === 0) {
      fetched.current = true;
      submit({}); // Mark step as done
      return;
    }

    if (applications.length > 1) {
      setSubmitButtonText('Next');
    }

    setCanSubmit(true);
    setApps(applications);
    setIsLoadingStepData(false);
    trackAccountFlowEvent(stepViewedEvent, {});
  }, [
    data,
    error,
    loading,
    setError,
    setIsLoadingStepData,
    trackAccountFlowEvent,
    submit,
    setCanSubmit,
    setSubmitButtonText,
  ]);

  const currentApp = useMemo(() => apps.find((app) => !app.done), [apps]);
  const isLastApp = useMemo(() => apps.findIndex((app) => !app.done) === apps.length - 1, [apps]);

  useEffect(() => {
    if (isLastApp) {
      setSubmitButtonText('Continue');
    }
  }, [apps, isLastApp, setSubmitButtonText]);

  const handleSubmit = useCallback(
    async (e: React.FormEvent<HTMLFormElement>) => {
      e.preventDefault();
      if (!currentApp) {
        return;
      }

      setIsSubmitting(true);
      trackAccountFlowEvent(AccountFlowAnalyticsEvents.ConsoleFlowStepButtonClicked, {
        button_name: submitButtonText,
        step_details: [{ appId: currentApp.id, appName: currentApp.displayName }],
      });

      try {
        if (currentApp.id == cdeAppId) {
          await updateAccountConfigApi({
            variables: {
              input: {
                accountId,
                config: {
                  mailForCDEUpdates: cdeEmail,
                },
              },
            },
          });
        }

        if (isLastApp) {
          await submit({}); // Call the submit function to mark the step as done
          return;
        }

        // mark app as done
        setApps((prevApps) =>
          prevApps.map((app) => {
            if (app.id === currentApp.id) {
              return { ...app, done: true };
            }
            return app;
          }),
        );
      } catch (error: any) {
        toast({ status: ToastStatus.error, text: error.message });
      } finally {
        setIsSubmitting(false);
      }
    },
    [
      currentApp,
      setIsSubmitting,
      trackAccountFlowEvent,
      submitButtonText,
      isLastApp,
      updateAccountConfigApi,
      accountId,
      cdeEmail,
      submit,
      toast,
    ],
  );

  if (!currentApp) {
    return null;
  }

  return (
    <ApplicationsSettingsWrapper data-testid="applications-settings-container">
      {/* Step submission form */}
      <form id="flow-steps" onSubmit={handleSubmit} />

      <AppHeader app={currentApp} />
      {currentApp.id === cdeAppId ? (
        <CDESettings
          cdeContactEmail={cdeEmail}
          setCanSubmit={setCanSubmit}
          setCdeEmail={setCdeEmail}
        />
      ) : (
        <div> I should be an iframe with a form and a save button.</div>
      )}
    </ApplicationsSettingsWrapper>
  );
};

const ApplicationsSettingsWrapper = styled.div`
  display: flex;
  flex-direction: column;
  padding: 20px 30px 20px 30px;
  gap: 10px;
  height: 100%;
`;
