import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { AddressInput, Tags } from '../../types';
import { CreateUserInput } from '../users';

export interface CreateAccountOwnerVariables {
  input: CreateAccountOwnerInput;
}

export interface CreateAccountOwnerInput {
  accountId: number;
  email: string;
  username?: string;
  password?: string;
  phoneNumber?: string;
  firstName?: string;
  lastName?: string;
  tag?: Tags;
  address?: AddressInput;
  vcUserMetadata?: CreateUserInput;
  npi?: string;
  tin?: string[];
}
export interface CreateAccountOwnerResult {
  success?: boolean;
}

const createAccountOwnerMutation = gql`
  mutation createAccountOwner($input: CreateAccountOwnerInput!) {
    createAccountOwner(input: $input) {
      success
    }
  }
`;

export function useCreateAccountOwnerMutation(
  options?: MutationHookOptions<CreateAccountOwnerResult, CreateAccountOwnerVariables>,
) {
  return useMutation(createAccountOwnerMutation, options);
}
