export const env = (window as any).$vim_environment?.APP_ENV;

export const isLocalEnvironment = window.location.hostname === 'localhost';

/** Old & New console have same origin in all environments, except local environment (because of different port).
 * @example https://console.dev.devim.io
 */
export function getOldConsoleOrigin() {
  return isLocalEnvironment ? `http://localhost:5000` : window.location.origin;
}
