import { AccountFlow } from '@/types';
import { gql, QueryHookOptions, useQuery } from '@apollo/client';

const getActiveAccountFlowQuery = gql`
  query GetActiveAccountFlow($accountId: Int!) {
    getActiveAccountFlow(accountId: $accountId) {
      flow {
        id
        type
        status
        steps {
          id
          flowId
          done
          type
          createdAt
          updatedAt
          isMandatory
        }
        accountId
      }
    }
  }
`;

interface GetActiveAccountFlowQuery {
  getActiveAccountFlow: { flow: AccountFlow | null };
}

interface GetActiveAccountFlowInput {
  accountId: number;
}

export const useGetActiveAccountFlow = (
  options?: QueryHookOptions<GetActiveAccountFlowQuery, GetActiveAccountFlowInput>,
) => useQuery(getActiveAccountFlowQuery, options);
