import {
  ApolloClient,
  ApolloLink,
  HttpLink,
  InMemoryCache,
  OperationVariables,
  QueryOptions,
} from '@apollo/client';
import { onError } from '@apollo/client/link/error';
import { GRAPHQL_CONSOLE_SERVER_URL } from './constants';
import { authManager } from './authManager';
import { removeTypenameFromVariables } from './stripTypenameApolloLink';
import { cacheTypePolicies } from './cache-type-policies';

const httpConsoleLink = new HttpLink({ uri: GRAPHQL_CONSOLE_SERVER_URL });
const PUBLIC_OPERATIONS = new Set([
  'sendPasswordResetEmail',
  'refreshTokenToConsole',
  'initiateLoginWithMFA',
  'completeLoginWithMFA',
]);

const removeTypenameLink = removeTypenameFromVariables({
  operationNames: ['saveApplicationVersionSubmission', 'findAllConsoleUserOrganizations'],
});

const authMiddlewareLink = new ApolloLink((operation, forward) => {
  if (PUBLIC_OPERATIONS.has(operation?.operationName)) {
    return forward(operation);
  }

  const accessToken = authManager.getAccessToken();
  if (accessToken) {
    operation.setContext(({ headers = {} }) => ({
      headers: {
        ...headers,
        authorization: accessToken,
      },
    }));
  }

  return forward(operation);
});

const errorLink = onError(({ graphQLErrors, networkError, operation }) => {
  graphQLErrors?.forEach(({ message, path, extensions }) =>
    console.error('[GraphQL error]', { operation, message, path, extensions }),
  );
  networkError && console.error(`[Network error]`, { operation, networkError });
});

export const gqlConsoleClient = new ApolloClient({
  link: ApolloLink.from([authMiddlewareLink, errorLink, removeTypenameLink, httpConsoleLink]),
  cache: new InMemoryCache({
    typePolicies: cacheTypePolicies,
  }),
});

export async function gqlClientQuery<TData = any, TVariables = OperationVariables>(
  query: QueryOptions<TVariables, TData>['query'],
  input: QueryOptions<TVariables, TData>['variables'],
  options?: GqlClientQueryOptions,
): Promise<TData> {
  const client = options?.client ? options.client : gqlConsoleClient;

  return (
    await client.query<TData, TVariables>({
      query,
      variables: input,
      context: options?.context,
      fetchPolicy: options?.fetchPolicy,
      errorPolicy: options?.errorPolicy,
    })
  )?.data;
}

export type GqlClientQueryOptions = Pick<
  QueryOptions<any, any>,
  'context' | 'fetchPolicy' | 'errorPolicy'
> & {
  client?: ApolloClient<object>;
};
