import React, { ElementRef, useCallback, useMemo, useRef, useState } from 'react';
import { ReactCrop, type Crop } from 'react-image-crop';
import styled from 'styled-components';
import CircledPlus from '../../../assets/icons/circled-plus.svg';
import { sanitizeSvgFile } from '../../../utils/svgSanitizer.util';
import { CropModal } from './CropModal';
import { addPaddingToImage, loadImageFromUrl } from './cropperHelperFunctions';
import { useToast } from '../../toast/use-toast';
import { ToastStatus } from '../../../types';
interface ImageUploadProps {
  cropMetadata?: Partial<ReactCrop['props']>;
  imageUrl: string;
  canvasWidth: number;
  canvasHeight: number;
  maxImageWidthInCanvas: number;
  maxImageHeightInCanvas: number;

  onImageUpload: (blob: Blob | null) => void;
}

const sanitizeFileForCrop = async (e: React.ChangeEvent<HTMLInputElement>) => {
  const uploadedFile = e.target.files?.[0];
  if (!uploadedFile) {
    return { file: undefined, errors: ['No file uploaded'] };
  }

  const { type, name } = uploadedFile;

  // Sanitize SVG files for security
  if (type.includes('svg') || name.toLowerCase().endsWith('.svg')) {
    try {
      const sanitizationResult = await sanitizeSvgFile(uploadedFile);

      if (!sanitizationResult.isValid) {
        console.error('SVG validation failed:', sanitizationResult.errors);

        return { file: undefined, errors: sanitizationResult.errors };
      }

      // Use the sanitized blob instead of the original file
      if (sanitizationResult.sanitizedBlob) {
        const sanitizedFile = new File([sanitizationResult.sanitizedBlob], name, {
          type: 'image/svg+xml',
        });

        return { file: sanitizedFile, errors: [] };
      }
    } catch (error) {
      console.error('SVG sanitization error:', error);

      return {
        file: undefined,
        errors: ['Failed to process SVG file. Please try a different file.'],
      };
    }
  }

  return { file: uploadedFile, errors: [] };
};

export const ImageUpload: React.FC<ImageUploadProps> = ({
  cropMetadata,
  imageUrl: originalImageUrl,
  canvasWidth,
  canvasHeight,
  maxImageWidthInCanvas,
  maxImageHeightInCanvas,
  onImageUpload,
}: ImageUploadProps) => {
  const [fileUrl, setFileUrl] = React.useState<string>();
  const [toast] = useToast();

  const inputRef = useRef<ElementRef<'input'>>(null);

  const [initialCropData, setInitialCropData] = useState<Crop>();

  const onClick = useCallback(() => {
    inputRef.current?.click();
  }, []);

  const onImageChange = useCallback(
    async (e: React.ChangeEvent<HTMLInputElement>) => {
      const { file: fileForCrop, errors } = await sanitizeFileForCrop(e);

      if (!fileForCrop || errors.length > 0) {
        toast({
          status: ToastStatus.error,
          text: errors.join(', ') || 'Failed to process file. Please try a again.',
        });
        return;
      }

      const originalImageBlobUrl = URL.createObjectURL(fileForCrop);

      const image = await loadImageFromUrl(originalImageBlobUrl);

      /** Add padding around image, so crop selection is more flexible as its not limited by original image size */
      const { imageWithPaddingUrl } = addPaddingToImage({
        image,
        outputWidth: canvasWidth,
        outputHeight: canvasHeight,
        maxCenteredImageWidth: maxImageWidthInCanvas,
        maxCenteredImageHeight: maxImageHeightInCanvas,
      });

      setFileUrl(imageWithPaddingUrl);
      let width, height;
      if (cropMetadata?.aspect) {
        width = (canvasWidth / cropMetadata.aspect) * 2;
        height = (canvasHeight / cropMetadata.aspect) * 2;
      } else {
        width = canvasWidth * 0.8;
        height = canvasHeight * 0.8;
      }
      const x = (canvasWidth - width) / 2;
      const y = (canvasHeight - height) / 2;
      const initialCropAroundImage: Crop = {
        width,
        height,
        unit: 'px',
        x,
        y,
      };

      setInitialCropData(initialCropAroundImage);

      if (inputRef.current?.value) {
        inputRef.current.value = '';
      }
    },
    [
      canvasHeight,
      canvasWidth,
      cropMetadata?.aspect,
      maxImageHeightInCanvas,
      maxImageWidthInCanvas,
    ],
  );

  const onCloseModal = useCallback(() => {
    setFileUrl(undefined);
  }, []);

  const onCropSaved = useCallback(
    (blob: Blob | null) => {
      onImageUpload(blob);
      onCloseModal();
    },
    [onCloseModal, onImageUpload],
  );

  const mergedCropMetadata = useMemo(() => {
    return {
      crop: initialCropData,
      ...(cropMetadata || {}),
    };
  }, [cropMetadata, initialCropData]);

  return (
    <>
      {!!fileUrl && (
        <CropModal
          cropMetadata={mergedCropMetadata}
          imageUrl={fileUrl}
          onClose={onCloseModal}
          onSave={onCropSaved}
        />
      )}

      <PlusContainer onClick={onClick} type="button">
        <img src={originalImageUrl || CircledPlus} />
        <input
          ref={inputRef}
          type="file"
          accept=".png, .svg"
          hidden
          name="uploadedImage"
          onChange={onImageChange}
        />
      </PlusContainer>
    </>
  );
};

const PlusContainer = styled.button`
  border: 1px solid #bdbdbd;
  border-radius: 10px;
  width: 100px;
  height: 100px;
  display: flex;
  align-items: center;
  justify-content: center;
`;
