import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { AddressInput, Input, Tags } from '../../types';
import { UserFragmentDoc } from './user-fragment';

export const getUserErrorMessage = (error?: any): { name: string; message: string } | null => {
  const errorMessage = error?.message;
  if (
    errorMessage?.includes('linked') &&
    error?.graphQLErrors?.[0]?.extensions?.code === 'CONFLICT'
  ) {
    return {
      name: 'linkedEhrUser',
      message: 'EHR Username is already associated with another user',
    };
  } else if (
    errorMessage?.includes('email') &&
    error?.graphQLErrors?.[0]?.extensions?.code === 'CONFLICT'
  ) {
    return {
      name: 'email',
      message: 'User with provided email already exists',
    };
  }
  return null;
};

export interface CreateUserMutation {
  createUser?: CreateUserInput;
}

export interface CreateUserInput {
  email?: string;
  username?: string;
  password?: string;
  phoneNumber?: string;
  organizationId: number;
  products?: string[];
  npi?: string;
  tin?: string[];
  title?: string;
  titles?: string[] | null;
  roles?: string[] | null;
  address?: AddressInput | null;
  firstName: string;
  lastName: string;
  linkedEhrUser?: string;
  tag?: Tags;
  isOrgAdmin?: boolean;
  metadata?: CreateUserInputMetadata;
}

interface CreateUserInputMetadata {
  createType?: UserCreateType;
}

export enum UserCreateType {
  CONSOLE = 'console',
  POTENTIAL = 'potential',
  IMPORT = 'import',
  EHR_AUTO = 'ehr_auto',
}

const createUserMutation = gql`
  mutation createUser($input: CreateUserInput!) {
    createUser(input: $input) {
      ...UserFragment
    }
  }
  ${UserFragmentDoc}
`;

export function useCreateUserMutation(
  options?: MutationHookOptions<CreateUserMutation, Input<CreateUserInput>>,
) {
  return useMutation(createUserMutation, options);
}
