export function omitDeep<T, K extends string>(value: T, key: K): T {
  return omitDeepInner(value, key);
}

function omitDeepInner<T, K extends string>(value: T, key: K, known = new Map<any, any>()) {
  if (known.has(value)) {
    return known.get(value);
  }

  let modified = false;

  if (Array.isArray(value)) {
    const array: any[] = [];
    known.set(value, array);

    value.forEach((value, index) => {
      const result = omitDeepInner(value, key, known);
      modified ||= result !== value;

      array[index] = result;
    });

    if (modified) {
      return array;
    }
  } else if (isPlainObject(value)) {
    const obj = Object.create(Object.getPrototypeOf(value));
    known.set(value, obj);

    Object.keys(value).forEach((k) => {
      if (k === key) {
        modified = true;
        return;
      }

      const result = omitDeepInner(value[k], key, known);
      modified ||= result !== value[k];

      obj[k] = result;
    });

    if (modified) {
      return obj;
    }
  }

  return value;
}

function isPlainObject(obj: any): obj is Record<string | number, any> {
  return (
    obj !== null &&
    typeof obj === 'object' &&
    (Object.getPrototypeOf(obj) === Object.prototype || Object.getPrototypeOf(obj) === null)
  );
}
