import * as React from 'react';
import { cn } from '../../lib/utils';
import { VariantProps, cva } from 'class-variance-authority';

const textareaVariants = cva(
  'flex min-h-[80px] w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50  disabled:border-opacity-30 disabled:text-gray-500',
  {
    variants: {
      variant: {
        gray: 'text-gray-6 placeholder:text-gray-7',
      },
      text: {
        small: 'text-sm placeholder:text-sm',
      },
      font: {
        medium: 'font-medium placeholder:font-normal',
      },
      border: {
        blue: 'border-blue-6 focus:border-2',
        black: 'border-black',
      },
    },
    defaultVariants: {
      variant: 'gray',
      text: 'small',
      font: 'medium',
      border: 'black',
    },
  },
);

export interface TextareaProps
  extends React.TextareaHTMLAttributes<HTMLTextAreaElement>,
    VariantProps<typeof textareaVariants> {
  asChild?: boolean;
  wrapperClassName?: string;
}

const Textarea = React.forwardRef<HTMLTextAreaElement, TextareaProps>(
  ({ wrapperClassName, className, variant, font, border, ...props }, ref) => {
    return (
      <div className={cn('relative w-full', wrapperClassName)}>
        <textarea
          className={cn(textareaVariants({ variant, font, border, className }), className)}
          ref={ref}
          {...props}
        />
        {props.maxLength && (
          <div className="text-right text-gray-500 text-xs absolute bottom-2 right-3">
            {(props.value as string)?.length || 0}/{props.maxLength}
          </div>
        )}
      </div>
    );
  },
);
Textarea.displayName = 'Textarea';

export { Textarea };
