import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { DataSourceApplication } from '../../types';

export type CreateDataSourceApplicationInput = {
  accountId: number;
  dataSourceId: number;
} & Pick<DataSourceApplication, 'applicationId' | 'config'>;

export interface CreateDataSourceApplicationMutation {
  success?: boolean;
}

export interface CreateDataSourceApplicationArgs {
  input: CreateDataSourceApplicationInput;
}

export const createDataSourceApplicationMutation = gql`
  mutation CreateDataSourceApplication($input: CreateDataSourceApplicationInput!) {
    createDataSourceApplication(input: $input) {
      success
    }
  }
`;

export function useCreateDataSourceApplicationMutation(
  options?: MutationHookOptions<
    CreateDataSourceApplicationMutation,
    CreateDataSourceApplicationArgs
  >,
) {
  return useMutation(createDataSourceApplicationMutation, options);
}
