import {
  gql,
  LazyQueryHookOptions,
  QueryHookOptions,
  useLazyQuery,
  useQuery,
} from '@apollo/client';
import { AccountAppStatus } from '../../types';
import { Product } from '@getvim-os/types';

export interface FindUsagesOfAppByAccountIdVariables {
  accountId: number;
  appId: Product | string;
}

export interface FindUsagesOfAppByAccountIdVariablesInput {
  input: FindUsagesOfAppByAccountIdVariables;
}

export interface FindUsagesOfAppByAccountIdQuery {
  findUsagesOfAppByAccountId?: AccountAppStatus;
}

const findUsagesOfAppByAccountIdQuery = gql`
  query FindUsagesOfAppByAccountId($input: FindUsagesOfAppByAccountIdInput!) {
    findUsagesOfAppByAccountId(input: $input) {
      organizationsUsingApplication
    }
  }
`;

export function useFindUsagesOfAppByAccountIdLazyQuery(
  options?: LazyQueryHookOptions<
    FindUsagesOfAppByAccountIdQuery,
    FindUsagesOfAppByAccountIdVariablesInput
  >,
) {
  return useLazyQuery(findUsagesOfAppByAccountIdQuery, options);
}

export const useFindUsagesOfAppByAccountIdQuery = (
  options?: QueryHookOptions<
    FindUsagesOfAppByAccountIdQuery,
    FindUsagesOfAppByAccountIdVariablesInput
  >,
) => useQuery(findUsagesOfAppByAccountIdQuery, options);
