import { gql, QueryHookOptions, useQuery } from '@apollo/client';
import { VimAdmin } from '../../types';

export interface GetAdminsResponse {
  getAdmins: VimAdmin[];
}

export const getAdminsQuery = gql`
  query getAdmins {
    getAdmins {
      id
      email
    }
  }
`;

export function useGetAdminsQuery(options?: QueryHookOptions<GetAdminsResponse>) {
  return useQuery(getAdminsQuery, options);
}
