import { gql } from '@apollo/client';
import { GqlClientQueryOptions, gqlClientQuery } from '../../common/gqlClient';
import { IsExist } from '../../types';

export interface DoesEmailExistQuery {
  doesEmailExist: IsExist;
}

export interface DoesEmailExistVariables {
  email: string;
}

const doesEmailExistQuery = gql`
  query doesEmailExist($email: String!) {
    doesEmailExist(email: $email) {
      isExist
      parentAccountId
      organizationId
      accountId
    }
  }
`;

export const doesEmailExist = async (email: string, options?: GqlClientQueryOptions) => {
  return (
    await gqlClientQuery<DoesEmailExistQuery, DoesEmailExistVariables>(
      doesEmailExistQuery,
      {
        email,
      },
      { fetchPolicy: 'no-cache', ...options },
    )
  )?.doesEmailExist;
};
