import styled from '@emotion/styled';
import { FormControlLabel, CheckboxProps, Checkbox } from '@mui/material';
import { ReactNode, forwardRef } from 'react';
import './CheckboxField.less';

export const CheckboxField: React.FC<CheckboxProps & { children: ReactNode[] | ReactNode }> =
  forwardRef(function CheckboxField({ children, sx, ...props }, ref) {
    return (
      <StyledFormControlLabel
        sx={sx}
        control={<StyledCheckbox {...props} ref={ref} />}
        label={<>{children}</>}
      />
    );
  });

const StyledFormControlLabel = styled(FormControlLabel)`
  display: flex;
  gap: 8px;
  align-items: center;
  margin-left: unset;
  width: fit-content;
`;

const StyledCheckbox = styled(Checkbox)`
  padding: 0px;
`;
