import React from 'react';
import { AccountFlowStepProps } from '../shared';

interface StepContextProps extends AccountFlowStepProps {
  accountId: number;
  canSubmit: boolean;
  submitButtonText: string;
  totalSteps: number;
  currentStepIndex: number;
  setCanSubmit: (canSubmit: boolean) => void;
  setSubmitButtonText: (text: string) => void;
  setIsLoadingStepData: (isLoading: boolean) => void;
  setError: (error: string) => void;
}
export const StepContext = React.createContext<StepContextProps | undefined>(undefined);
export const useAccountFlowStepContext = () => {
  const context = React.useContext(StepContext);
  if (context === undefined) {
    throw new Error('useStepContext must be used within a StepContentWrapper');
  }
  return context;
};
