import { gql, MutationHookOptions, useMutation } from '@apollo/client';

export interface VerifyTokenRequestVariables {
  input?: VerifyAppTokenInput;
}

export type VerifyAppTokenInput = {
  appId: string;
  launchId: string;
  token: string;
  organizationId?: number;
};

export type VerifyAppTokenResponse = {
  verifyAppToken: {
    isValid: boolean;
  };
};

export const verifyAppToken = gql`
  mutation verifyAppToken($input: VerifyAppTokenInput) {
    verifyAppToken(input: $input) {
      isValid
    }
  }
`;

export function useVerifyAppTokenMutation(
  options?: MutationHookOptions<VerifyAppTokenResponse, VerifyTokenRequestVariables>,
) {
  return useMutation(verifyAppToken, options);
}
