import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { AccountAuth, Input } from '../../types';

export interface RotateAccountAuthInput {
  accountId: number;
  clientSecret?: string;
}

export interface RotateAccountAuthResponse {
  rotateAccountAuth: AccountAuth;
}

export const rotateAccountAuthMutation = gql`
  mutation rotateAccountAuth($input: RotateAccountAuthInput!) {
    rotateAccountAuth(input: $input) {
      clientId
      clientSecret
    }
  }
`;

export function useRotateAccountAuthMutation(
  options?: MutationHookOptions<RotateAccountAuthResponse, Input<RotateAccountAuthInput>>,
) {
  return useMutation(rotateAccountAuthMutation, options);
}
