import { createContext, useContext } from 'react';
import type useEmblaCarousel from 'embla-carousel-react';
import { HeadlessCarousel } from './useInitCarousel';

type CarouselContextProps = {
  carouselRef: ReturnType<typeof useEmblaCarousel>[0] | null;
  carouselApi: ReturnType<typeof useEmblaCarousel>[1] | null;
};
export const CarouselContext = createContext<CarouselContextProps>({
  carouselRef: null,
  carouselApi: null,
});
export const useCarouselContext = () => {
  const context = useContext(CarouselContext);

  if (!context) {
    throw new Error('useCarousel must be used within a <Carousel />');
  }

  return context;
};

export const CarouselProvider = ({
  children,
  HeadlessCarousel,
}: {
  children: React.ReactNode;
  HeadlessCarousel: HeadlessCarousel;
}) => {
  const carouselRef = HeadlessCarousel[0];
  const carouselApi = HeadlessCarousel[1];

  const value = {
    carouselRef,
    carouselApi,
  };
  return <CarouselContext.Provider value={value}>{children}</CarouselContext.Provider>;
};
