import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { Input, UserType } from '../../types';

export interface SendActivationEmailMutation {
  resendActivationMail: boolean;
}

export interface SendActivationEmailInput {
  id: string;
  email: string;
  userType: UserType;
  forceSend: boolean;
}

const sendActivationEmailMutation = gql`
  mutation ResendActivationMail($input: ResendActivationMailInput!) {
    resendActivationMail(input: $input)
  }
`;

export function useSendActivationEmailMutation(
  options?: MutationHookOptions<SendActivationEmailMutation, Input<SendActivationEmailInput>>,
) {
  return useMutation(sendActivationEmailMutation, options);
}
