import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { Input } from '../../types';

export interface DeleteVimAdminMutation {
  deleteVimAdmin: {
    success: boolean;
  };
}

export interface DeleteVimAdminInput {
  id: string;
}

const deleteVimAdminMutation = gql`
  mutation deleteVimAdmin($input: DeleteVimAdminInput!) {
    deleteVimAdmin(input: $input) {
      success
    }
  }
`;

export function useDeleteVimAdminMutation(
  options?: MutationHookOptions<DeleteVimAdminMutation, Input<DeleteVimAdminInput>>,
) {
  return useMutation(deleteVimAdminMutation, options);
}
