import { gql, useMutation, MutationHookOptions } from '@apollo/client';
import { Address, Input, Tags } from '../../types';

export interface UserInput {
  email?: string;
  phoneNumber?: string;
  organizationId: number;
  products?: string[];
  npi?: string;
  tin?: string[];
  title?: string;
  roles?: string[];
  address?: Address;
  firstName: string;
  lastName: string;
  linkedEhrUser?: string;
  tag?: Tags;
  isOrgAdmin?: boolean;
}

export interface ImportedUserInput {
  email?: string;
  phoneNumber?: string;
  organizationId: number;
  products?: string[];
  npi?: string;
  tin?: string[];
  title?: string;
  roles?: string[];
  address?: Address;
  firstName: string;
  lastName: string;
  linkedEhrUser?: string;
}

export interface ImportUsers {
  importedUsers: ImportedUserInput[];
  organizationId: number;
  fileName: string;
  requestingUser: string;
}

export interface ImportUsersMutation {
  importUsers?: ImportUsers;
}

const importUsersMutation = gql`
  mutation importUsers($input: ImportUsersInput!) {
    importUsers(input: $input) {
      success
    }
  }
`;

export function useImportUsersMutation(
  options?: MutationHookOptions<ImportUsersMutation, Input<ImportUsers>>,
) {
  return useMutation(importUsersMutation, options);
}
