import { gql, QueryHookOptions, useQuery } from '@apollo/client';
import { ExternalRole, Organization } from '../../types';
import { gqlClientQuery, GqlClientQueryOptions } from '../../common';

export interface ConsoleMeResponse {
  id?: string;
  firstName?: string;
  lastName?: string;
  email?: string;
  accountId?: number;
  externalRoles?: ExternalRole[];
  organization?: Partial<Pick<Organization, 'id' | 'name'>>;
}

export interface ConsoleMeQuery {
  consoleMe: ConsoleMeResponse;
}

const consoleMeQuery = gql`
  query consoleMe {
    consoleMe {
      id
      firstName
      lastName
      email
      accountId
      externalRoles
      organization {
        id
        name
      }
    }
  }
`;

export function useConsoleMeQuery(options?: QueryHookOptions<ConsoleMeQuery>) {
  return useQuery(consoleMeQuery, options);
}

export async function consoleMe(options?: GqlClientQueryOptions) {
  return await gqlClientQuery<ConsoleMeQuery>(consoleMeQuery, undefined, {
    fetchPolicy: 'no-cache',
    ...options,
  });
}
