import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { AddressInput, ExternalRole, Tags } from '../../types';
import { AccountPermissions } from './accountPermissions';
import { CreateUserInput } from '../users';

export interface UpdateConsoleUserVariables {
  input?: UpdateConsoleUserInput;
}

export interface UpdateConsoleUserInput {
  accountId: number;
  externalId: string;
  email?: string;
  username?: string;
  password?: string;
  phoneNumber?: string;
  firstName?: string;
  lastName?: string;
  tag?: Tags;
  address?: AddressInput;
  permittedOrganizations?: AccountPermissions;
  externalRoles?: ExternalRole[];
  npi?: string;
  tin?: string[];
  vcUserMetadata?: CreateUserInput;
}
export interface UpdateConsoleUserResult {
  success?: boolean;
}

const updateConsoleUserMutation = gql`
  mutation updateConsoleUser($input: UpdateConsoleUserInput!) {
    updateConsoleUser(input: $input) {
      success
    }
  }
`;

export function useUpdateConsoleUserMutation(
  options?: MutationHookOptions<UpdateConsoleUserResult, UpdateConsoleUserVariables>,
) {
  return useMutation(updateConsoleUserMutation, options);
}
