import { gql, LazyQueryHookOptions, useLazyQuery } from '@apollo/client';
import { PotentialUserMetadata } from '../../types';

export interface FindAllPotentialUsersVariables {
  input: { organizationId: number };
}

export interface FindAllPotentialUsersQuery {
  findAllPotentialUsers?: PotentialUserMetadata[];
}

const findAllPotentialUsersQuery = gql`
  query findAllPotentialUsers($input: findAllPotentialUsersInput) {
    findAllPotentialUsers(input: $input) {
      id
      organizationId
      linkedEhrUser
      createdAt
      npi
      tin
      address {
        addressLine1
        addressLine2
        city
        state
        zip
      }
      firstName
      lastName
      email
      phoneNumber
      isDismissed
      isVerified
      updatedAt
    }
  }
`;

export function useFindAllPotentialUsersLazyQuery(
  options?: LazyQueryHookOptions<FindAllPotentialUsersQuery, FindAllPotentialUsersVariables>,
) {
  return useLazyQuery(findAllPotentialUsersQuery, options);
}
