import { Dialog } from '@mui/material';
import React, { FC } from 'react';
import styled from 'styled-components';
import { IconButton } from '.';

interface IFrameDialogProps {
  open: boolean;
  url: string;
  onClose: () => void;
}

export const IFrameDialog: FC<IFrameDialogProps> = ({ open, url, onClose }: IFrameDialogProps) => {
  return (
    <Dialog
      open={open}
      PaperProps={{
        style: {
          width: '80%',
          height: '80%',
          maxHeight: 'unset',
          maxWidth: '1000px',
          padding: '40px',
        },
      }}
    >
      <IFrameStyled src={url} sandbox="allow-scripts allow-same-origin" />
      <CloseButton fontIconName="icon-x-2" onClick={onClose} />
    </Dialog>
  );
};

const IFrameStyled = styled.iframe`
  width: 100%;
  height: 100%;
  border-width: 0; /** override iframe default to prevent horizontal scroll */
`;

const CloseButton = styled(IconButton)`
  position: absolute;
  top: 15px;
  right: 12px;
`;
