import React, { ChangeEvent, useCallback, useState } from 'react';
import styled from 'styled-components';
import '../modal-parts/modal.scss';
import { useDebounce } from '../../../hooks';
import { InlineLoader } from '..';

export interface SearchInputProps {
  searchTerm: string;
  onChange: (newValue: string) => void;
  placeHolder?: string;
  onClick?: () => void;
  inputWidth?: string;
  inputHeight?: string;
  className?: string;
  onEnterPress?: (newValue: string) => void;
  debounceDelay?: number;
}

export const SearchInput: React.FunctionComponent<SearchInputProps> = ({
  searchTerm,
  onChange,
  placeHolder,
  onClick,
  inputWidth,
  inputHeight,
  className,
  onEnterPress,
  debounceDelay,
}: SearchInputProps) => {
  const [isDebouncing, setIsDebouncing] = useState(false);

  const onChangeDebounceFinish = useCallback(
    (value: string) => {
      setIsDebouncing(false);
      onChange(value);
    },
    [onChange],
  );

  const startDebounceOnChange = useDebounce(onChangeDebounceFinish, debounceDelay);

  const handleSearchInputChange = useCallback(
    ({ currentTarget }: ChangeEvent<HTMLInputElement>) => {
      const { value } = currentTarget;

      if (debounceDelay) {
        setIsDebouncing(true);
        startDebounceOnChange?.(value);
      } else {
        onChange(value);
      }
    },
    [debounceDelay, startDebounceOnChange, onChange],
  );

  const handleKeyDown = (event) => {
    if (onEnterPress && event.key === 'Enter') {
      onEnterPress(event.target.value);
    }
  };

  return (
    <InputContainer className={className}>
      <InnerSearchInput
        value={debounceDelay ? undefined : searchTerm ?? ''}
        onChange={handleSearchInputChange}
        placeholder={placeHolder || 'Search'}
        onClick={onClick}
        style={{ width: inputWidth, height: inputHeight }}
        onKeyDown={onEnterPress ? handleKeyDown : undefined}
        defaultValue={debounceDelay ? searchTerm : undefined}
      />
      <SearchIcon className="icon-search-2" />
      {isDebouncing && <InlineLoaderStyled />}
    </InputContainer>
  );
};

const InputContainer = styled.div`
  position: relative;
  color: ${(props) => props.theme.colors.textHeading};
`;

const InnerSearchInput = styled.input`
  width: ${(props) => props.style?.width || '220px'};
  height: 34px;
  font-size: ${(props) => props.theme.fontSizes.normal};
  padding: 2px 10px 0 32px;
  border: 1px solid ${(props) => props.theme.colors.textHeading};
  border-radius: 4px;
  box-sizing: border-box;

  ::-webkit-input-placeholder {
    font-style: italic;
    font-size: 12px;
  }
`;

const SearchIcon = styled.i`
  position: absolute;
  left: 10px;
  top: 10px;
  font-size: 16px;
  font-weight: bold;
  transform: scaleX(-1) translateY(-1px);
`;

const InlineLoaderStyled = styled(InlineLoader)`
  position: absolute;
  display: flex;
  top: 0.5rem;
  right: 0.5rem;
  transform: scale(0.8);
`;
