import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { Input, UserType } from '../../types';

export interface ResendActivationMailMutationResult {
  resendActivationMail: boolean;
}

export interface ResendActivationMailInput {
  id: string | number;
  email: string;
  userType: UserType;
  forceSend?: boolean;
}

export const resendActivationMailMutation = gql`
  mutation resendActivationMail($input: ResendActivationMailInput!) {
    resendActivationMail(input: $input)
  }
`;

export function useResendActivationMailMutation(
  options?: MutationHookOptions<
    ResendActivationMailMutationResult,
    Input<ResendActivationMailInput>
  >,
) {
  return useMutation(resendActivationMailMutation, options);
}
