import styled from 'styled-components';
import { useAccountFlowStepContext } from '../hooks/useAccountFlowStepContext';
import { StepFooter } from './StepFooter';
import { StepHeader } from './StepHeader';

interface StepLayoutProps {
  header?: string;
  simpleFooter?: boolean;
}

export const StepLayout: React.FC<StepLayoutProps> = ({ header, simpleFooter, children }) => {
  const { submitButtonText, isSubmitting, canSubmit, totalSteps, currentStepIndex } =
    useAccountFlowStepContext();
  return (
    <StepLayoutContainer>
      <StepHeader title={header} />
      <StepContent>{children}</StepContent>
      <StepFooter
        submitButtonText={submitButtonText}
        isSubmitting={isSubmitting}
        canSubmit={canSubmit}
        totalSteps={totalSteps}
        currentStepIndex={currentStepIndex}
        simpleFooter={simpleFooter}
      />
    </StepLayoutContainer>
  );
};

const StepLayoutContainer = styled.div`
  display: flex;
  flex-direction: column;
  height: 100%; /* Take full height of parent (StepWrapper) */
`;

const StepContent = styled.div`
  flex: 1;
  overflow: hidden; /* Important to prevent content overflow */
`;
