import { BkmdModal } from '@getvim/atomic-ui';
import React, { ElementRef, useCallback, useEffect, useRef, useState } from 'react';
import ReactCrop, { type Crop } from 'react-image-crop';
import 'react-image-crop/src/ReactCrop.scss';
import { ButtonContainer } from '../ButtonContainer';
import { TitleText } from '../title';
import styled from 'styled-components';
import { Button } from '@mui/material';
import * as CropperHelper from './cropperHelperFunctions';
import { GeneralTexts } from '../../../common';

export const DEFAULT_CROP_ASPECT = 1 / 3;
interface CropModalProps {
  imageUrl: string;
  onClose: () => void;
  onSave: (blob: Blob | null) => void;
  cropMetadata?: Partial<ReactCrop['props']>;
}

export const CropModal: React.FC<CropModalProps> = ({
  imageUrl,
  onClose,
  onSave,
  cropMetadata,
}) => {
  const [crop, setCrop] = useState<Crop | undefined>(cropMetadata?.crop);

  useEffect(() => {
    setCrop(cropMetadata?.crop);
  }, [cropMetadata?.crop]);

  const imageRef = useRef<ElementRef<'img'>>(null);

  const onCropChange = useCallback((c) => {
    setCrop(c);
  }, []);

  const onCloseModal = useCallback(() => {
    onClose();
  }, [onClose]);

  const onSaveCrop = useCallback(async () => {
    if (imageRef.current === null || !crop) {
      return;
    }
    const canvas = document.createElement('canvas');
    CropperHelper.canvasPreview(imageRef.current, canvas, crop);
    const imageBlob = await CropperHelper.toBlob(canvas);
    onSave(imageBlob);
  }, [imageRef, onSave, crop]);

  return (
    <StyledModal isOpen={true} className="modal">
      <TitleText>{GeneralTexts.CropImage}</TitleText>
      <CenterCropContainer>
        <CropContainer>
          <ReactCrop
            onChange={onCropChange}
            {...(cropMetadata?.aspect !== undefined ? { aspect: cropMetadata.aspect } : {})}
            {...(cropMetadata || {})}
            crop={crop || cropMetadata?.crop}
          >
            <Image ref={imageRef} src={imageUrl} style={{ width: 600 }} />
          </ReactCrop>
        </CropContainer>
      </CenterCropContainer>
      <ButtonContainer justifyContent="center">
        <MarginedButton variant="outlined" color="primary" onClick={onCloseModal}>
          {GeneralTexts.Cancel}
        </MarginedButton>
        <MarginedButton color="primary" variant="contained" onClick={onSaveCrop}>
          {GeneralTexts.Save}
        </MarginedButton>
      </ButtonContainer>
    </StyledModal>
  );
};

const CropContainer = styled.div`
  display: flex;
  justify-content: center;
  border: 1px solid black;
  max-width: fit-content;
`;

const CenterCropContainer = styled.div`
  display: flex;
  justify-content: center;
`;

const Image = styled.img`
  width: 100%;
  height: 100%;
`;

const MarginedButton = styled(Button)`
  margin-top: 1rem;
`;

const StyledModal = styled(BkmdModal)`
  text-align: center;
  &.dialog {
    width: fit-content;
  }
`;
