import { gql, LazyQueryHookOptions, useLazyQuery } from '@apollo/client';
import { Organization } from '../../types';

export interface GetOrganizationByIdVariables {
  id: number;
}

export interface GetOrganizationByIdQuery {
  getOrganizationById?: Organization;
}

const getOrganizationByIdQuery = gql`
  query getOrganizationById($id: Int!) {
    getOrganizationById(id: $id) {
      id
      name
      ehrSystem
      ehrUrl
      tin
      tins
      npi
      organizationKey
      products {
        name
        sources
        contentSources
        isDefaultVcUserProduct
      }
      identityProvider
      isSeamlessLoginAutoApproved
      shouldAutoCreatePotentialUsers
      accountId
      tag
      isOptOutFromVC
    }
  }
`;

export function useGetOrganizationByIdLazyQuery(
  options?: LazyQueryHookOptions<GetOrganizationByIdQuery, GetOrganizationByIdVariables>,
) {
  return useLazyQuery(getOrganizationByIdQuery, options);
}
