import { createContext, useContext, useState, Dispatch, SetStateAction, useCallback } from 'react';
import { ConsoleMeQuery, ConsoleMeResponse } from '../../api';

export type ConsoleMe = ConsoleMeQuery['consoleMe'];

export const enum UserArrivalSource {
  NONE = 'none',
  ACTIVATION_FLOW_SOURCE = 'activation-flow',
  RE_SIGN_FLOW_NEW_USER = 're-sign-flow-new-user',
  RE_SIGN_FLOW = 're-sign-flow',
  UPDATE_TOS_WITH_CDE_FLOW = 'update-tos-with-cde-flow',
  UPDATE_TOS_NEW_USER_FLOW = 'update-tos-new-user-flow',
}
interface UserContextData {
  user: ConsoleMe | undefined;
  setUser: Dispatch<SetStateAction<ConsoleMeResponse | undefined>>;
  isInitialLogin: boolean;
  setIsInitialLogin: Dispatch<SetStateAction<boolean>>;
  userArrivalSource: UserArrivalSource | undefined;
  setUserArrivalSource: Dispatch<SetStateAction<UserArrivalSource | undefined>>;
  clearUserContext: () => void;

  /** Remove these fields once we only use universal login */
  isInitLoadAccounts: boolean;
  setIsInitLoadAccounts: Dispatch<SetStateAction<boolean>>;
  isInitLoadOrganizations: boolean;
  setIsInitLoadOrganizations: Dispatch<SetStateAction<boolean>>;
}

export const UserContext = createContext<UserContextData>({} as UserContextData);

export const UserProvider = ({ children }) => {
  const context = useUserContextProvider();

  const { Provider } = UserContext;
  return <Provider value={context}>{children}</Provider>;
};

export const useUserContext = (): UserContextData => useContext(UserContext);

export const useUserContextProvider = (): UserContextData => {
  const [user, setUser] = useState<ConsoleMe | undefined>();
  const [isInitialLogin, setIsInitialLogin] = useState<boolean>(false);
  const [userArrivalSource, setUserArrivalSource] = useState<UserArrivalSource>();
  const [isInitLoadAccounts, setIsInitLoadAccounts] = useState(false);
  const [isInitLoadOrganizations, setIsInitLoadOrganizations] = useState(false);

  const clearUserContext = useCallback(() => {
    setUser(undefined);
    setUserArrivalSource(undefined);
    setIsInitialLogin(false);
    setIsInitLoadAccounts(false);
    setIsInitLoadOrganizations(false);
  }, []);

  return {
    user,
    setUser,
    isInitialLogin,
    setIsInitialLogin,
    userArrivalSource,
    setUserArrivalSource,
    clearUserContext,

    isInitLoadAccounts,
    setIsInitLoadAccounts,
    isInitLoadOrganizations,
    setIsInitLoadOrganizations,
  };
};
