import { gql, LazyQueryHookOptions, useLazyQuery } from '@apollo/client';
import { ExtendedConsoleUser } from '../../types';

export interface FindConsoleUserResponse {
  findConsoleUser: ExtendedConsoleUser;
}

export interface FindConsoleUserVariables {
  accountId?: number;
  externalId?: string;
}

export interface FindConsoleUserInput {
  input: FindConsoleUserVariables;
}

const findConsoleUser = gql`
  query FindConsoleUser($input: FindConsoleUserInput!) {
    findConsoleUser(input: $input) {
      createdAt
      activatedAt
      organizationId
      accountId
      externalId
      email
      phoneNumber
      blocked
      npi
      tin
      roles
      title
      products
      address {
        addressLine1
        addressLine2
        city
        state
        zip
        fullAddress
      }
      firstName
      lastName
      externalRoles
      activationSentAt
      linkedEhrUser
      permittedOrganizationsMetadata {
        id
        name
        accountId
      }
    }
  }
`;

export function useFindConsoleUserLazyQuery(
  options?: LazyQueryHookOptions<FindConsoleUserResponse, FindConsoleUserInput>,
) {
  return useLazyQuery(findConsoleUser, options);
}
