import { EnrichedAccount } from '@/types';
import { ApolloError } from '@apollo/client';
import { createContext } from 'react';

export interface AccountContextData {
  account: EnrichedAccount | undefined;
  isLoadingAccount: boolean;
  doneLoadingAccount: boolean;
  activationInProgress: boolean;
  setActivationInProgress: (inProgress: boolean) => void;
  fetchAccountError: ApolloError | undefined;
  changeAccount: (accountId: number) => void;
  refetchAccount: () => void;
  clearAccount: () => void;
}

/** The user account or selected account in accounts list. vim admins have no account initially */
export const AccountContext = createContext<AccountContextData>({} as AccountContextData);
