import { useFindOneConsoleUserOrganization } from '@/api/organizations/findOneConsoleUserOrganization';
import { ApolloError } from '@apollo/client';
import { Team, useFeatureFlag } from '@getvim/feature-flags-react';
import { createContext, useCallback, useContext, useMemo, useState } from 'react';
import { useUserContext } from './user-provider';
import { useOrganizationsListContext } from './OrganizationsListProvider';
import { useLogger } from './LoggerProvider';
import { useGetOneApplicationConsumingOrganizationLazy } from '../../api/applications';
import { useGetOrganizationByIdLazyQuery } from '../../api/organizations';
import { authManager } from '../../common';
import { DsConsumingOrganization, Key, Organization, ToastStatus } from '../../types';
import { AppConsumingOrganization } from '../../types/appConsumingOrganization';
import { useToast } from '../toast';

const isDsConsumingOrganization = (
  dsConsumingOrganizations: Organization[],
  orgId?: number,
): boolean =>
  !authManager.isVimAdmin() && !!orgId && dsConsumingOrganizations.some((org) => org.id === orgId);

const isAppConsumingOrganization = (
  appConsumingOrganizations: Pick<Organization, 'id'>[],
  orgId?: number,
): boolean =>
  !authManager.isVimAdmin() && !!orgId && appConsumingOrganizations.some((org) => org.id === orgId);

const isOwnedOrManagedOrganization = (
  ownedOrManagedOrgs: Organization[],
  orgId?: number,
): boolean =>
  authManager.isVimAdmin() || (!!orgId && ownedOrManagedOrgs.some((org) => org.id === orgId));

interface OrganizationContextData {
  organization: (Organization | DsConsumingOrganization | AppConsumingOrganization) | undefined;
  isLoadingOrganization: boolean;
  isDsConsumingOrganization: boolean;
  isAppConsumingOrganization: boolean;
  isOwnedOrManagedOrganization: boolean;
  fetchOrganizationError: ApolloError | undefined;
  organizationsApiWasCalled: boolean;
  organizationAndListReady: boolean;
  changeOrganization: (orgId: number, userEmail: string, isInit?: boolean) => void;
  refetchOrganization: () => void;
  clearOrganization: () => void;
  getLastOrganizationIdByEmail: (email: string) => number | undefined;
}

export const OrganizationContext = createContext<OrganizationContextData>(
  {} as OrganizationContextData,
);

export const OrganizationProvider = ({ children }) => {
  const context = useOrganizationContextProvider();

  const { Provider } = OrganizationContext;
  return <Provider value={context}>{children}</Provider>;
};

export const useOrganizationContext = (): OrganizationContextData =>
  useContext(OrganizationContext);

export const useOrganizationContextProvider = (): OrganizationContextData => {
  const logger = useLogger({ scope: 'OrganizationContextProvider' });
  const [toast] = useToast();
  const {
    organizationsList,
    dsConsumingOrganizationsList,
    appConsumingOrganizationsList,
    isLoadingOrganizationsList,
    wasGetAllOrganizationsCalled,
  } = useOrganizationsListContext();
  const { user } = useUserContext();
  const [loading, setLoading] = useState(false);
  const [organization, setOrganization] = useState<
    Organization | DsConsumingOrganization | AppConsumingOrganization | undefined
  >();
  const [organizationsApiWasCalled, setOrganizationsApiWasCalled] = useState<boolean>(false);

  const isSelectedOrgConsumingDs = useMemo(
    () => isDsConsumingOrganization(dsConsumingOrganizationsList, organization?.id),
    [dsConsumingOrganizationsList, organization?.id],
  );

  const isSelectedOrgConsumingApp = useMemo(
    () => isAppConsumingOrganization(appConsumingOrganizationsList, organization?.id),
    [appConsumingOrganizationsList, organization?.id],
  );

  const isSelectedOrgOwnedOrManaged = useMemo(
    () => isOwnedOrManagedOrganization(organizationsList, organization?.id),
    [organization, organizationsList],
  );

  const organizationAndListReady =
    !loading &&
    organizationsApiWasCalled &&
    !isLoadingOrganizationsList &&
    wasGetAllOrganizationsCalled;

  const [shouldUseFindOneConsoleUserOrganization] = useFeatureFlag({
    flagName: 'organization-console.shouldUseFindOneConsoleUserOrganization',
    defaultValue: false,
    team: Team.OMT,
  });

  const [findOneConsoleUserOrganization, { error: findOneConsoleUserOrganizationError }] =
    useFindOneConsoleUserOrganization({
      fetchPolicy: 'no-cache',
      onCompleted(result) {
        setLoading(false);
        const { organization } = result.findOneConsoleUserOrganization || {};
        if (organization) {
          setOrganization(organization);
        }
      },
      onError() {
        setLoading(false);
        toast({
          status: ToastStatus.error,
          text: 'Error occurred while fetching organization data',
        });
      },
    });

  const [getOrganization, { error: fetchOrganizationError }] = useGetOrganizationByIdLazyQuery({
    fetchPolicy: 'no-cache',
    onCompleted(getOrganizationRes) {
      setLoading(false);
      if (getOrganizationRes?.getOrganizationById)
        setOrganization(getOrganizationRes?.getOrganizationById);
    },
    onError(error) {
      setLoading(false);
      logger.error('getOrganization failed', {}, error as Error);
      toast({
        status: ToastStatus.error,
        text: 'Error occurred while consuming organization data',
      });
    },
  });

  const [
    getOneApplicationConsumingOrganization,
    { error: fetchOneApplicationConsumingOrganization },
  ] = useGetOneApplicationConsumingOrganizationLazy({
    fetchPolicy: 'no-cache',
    onCompleted(getOneApplicationConsumingOrganizationResponse) {
      setLoading(false);

      const appConsumingOrg =
        getOneApplicationConsumingOrganizationResponse?.getOneApplicationConsumingOrganization;

      if (appConsumingOrg) {
        setOrganization(appConsumingOrg);
      }
    },
    onError() {
      setLoading(false);
      toast({
        status: ToastStatus.error,
        text: 'Error occurred while fetching consuming organization data',
      });
    },
  });

  const fetchOrganization = useCallback(
    (orgId: number) => {
      setLoading(true);
      if (shouldUseFindOneConsoleUserOrganization) {
        findOneConsoleUserOrganization({ variables: { organizationId: orgId } });
        // TODO: Remove all other if conditions and use only this one after validating the FF in production
      } else if (isAppConsumingOrganization(appConsumingOrganizationsList, orgId)) {
        const appConsumingOrg = appConsumingOrganizationsList.find((org) => org.id === orgId);

        if (!user?.accountId || !appConsumingOrg) {
          return;
        }

        getOneApplicationConsumingOrganization({
          variables: {
            input: {
              accountId: user?.accountId,
              organizationId: orgId,
            },
          },
        });
      } else {
        getOrganization({ variables: { id: orgId } });
      }
      setOrganizationsApiWasCalled(true);
    },
    [
      shouldUseFindOneConsoleUserOrganization,
      appConsumingOrganizationsList,
      findOneConsoleUserOrganization,
      user?.accountId,
      getOneApplicationConsumingOrganization,
      getOrganization,
    ],
  );

  const refetchOrganization = useCallback(() => {
    if (!organization) return;
    fetchOrganization(organization.id);
  }, [organization, fetchOrganization]);

  const getEmailToLastOrganizationIdMapFromStorage = useCallback(():
    | Record<string, number>
    | undefined => {
    const rawValue = window.localStorage[Key.LAST_ORGANIZATIONS_IDS];
    return rawValue ? JSON.parse(rawValue) : undefined;
  }, []);

  const setEmailToLastOrganizationIdMapFromStorage = useCallback(
    (map: Record<string, number>): void => {
      const stringifiedMap = JSON.stringify(map);
      window.localStorage[Key.LAST_ORGANIZATIONS_IDS] = stringifiedMap;
    },
    [],
  );

  const getLastOrganizationIdByEmail = useCallback(
    (email: string) => {
      const emailToLastOrganizationIdMap = getEmailToLastOrganizationIdMapFromStorage();
      const lastOrganizationId = emailToLastOrganizationIdMap?.[email];
      if (organizationsList.some((org) => org.id === lastOrganizationId)) {
        return lastOrganizationId;
      }
      return undefined;
    },
    [getEmailToLastOrganizationIdMapFromStorage, organizationsList],
  );

  const setLastOrganizationIdByEmail = useCallback(
    (email: string, organizationId: number) => {
      const emailToLastOrganizationIdMap = getEmailToLastOrganizationIdMapFromStorage();

      const newMap = { ...emailToLastOrganizationIdMap, [email]: organizationId };

      setEmailToLastOrganizationIdMapFromStorage(newMap);

      return newMap;
    },
    [getEmailToLastOrganizationIdMapFromStorage, setEmailToLastOrganizationIdMapFromStorage],
  );

  const changeOrganization = useCallback(
    (orgId: number, userEmail: string, isInit: boolean = false) => {
      if (!isInit) {
        setLastOrganizationIdByEmail(userEmail, orgId);
      }
      fetchOrganization(orgId);
    },
    [fetchOrganization, setLastOrganizationIdByEmail],
  );

  const clearOrganization = useCallback(() => {
    setOrganization(undefined);
    setOrganizationsApiWasCalled(false);
    setLoading(false);
  }, []);

  return {
    isLoadingOrganization: loading,
    isDsConsumingOrganization: isSelectedOrgConsumingDs,
    isAppConsumingOrganization: isSelectedOrgConsumingApp,
    isOwnedOrManagedOrganization: isSelectedOrgOwnedOrManaged,
    fetchOrganizationError:
      fetchOrganizationError ||
      fetchOneApplicationConsumingOrganization ||
      findOneConsoleUserOrganizationError,
    organizationsApiWasCalled,
    organization,
    organizationAndListReady,
    changeOrganization,
    refetchOrganization,
    clearOrganization,
    getLastOrganizationIdByEmail,
  };
};
