import styled from '@emotion/styled';
import { InputAdornment, TextField, TextFieldProps } from '@mui/material';

export interface TextFieldCounterProps {
  maxLength: number;
  currentLength?: number;
}

export const TextFieldWithCounter: React.FC<TextFieldCounterProps & TextFieldProps> = ({
  maxLength,
  currentLength,
  ...props
}) => {
  return (
    <TextField
      {...props}
      inputProps={{
        maxLength,
        style: { ...props.inputProps?.style },
        ...props.inputProps,
      }}
      sx={{
        '& .MuiInputAdornment-root': {
          marginRight: '-5px',
        },
      }}
      InputProps={{
        endAdornment: (
          <InputAdornment position="end">
            <TextLengthCounter>
              {currentLength || 0}/{maxLength}
            </TextLengthCounter>
          </InputAdornment>
        ),
      }}
    />
  );
};

const TextLengthCounter = styled.div`
  font-size: 12px;
  color: #32333c;
`;
