import { gql, LazyQueryHookOptions, useLazyQuery } from '@apollo/client';
import { Organization } from '../../types';

export interface GetAllOrganizationsQuery {
  getAllOrganizations: {
    count: number;
    results: Organization[];
  };
}

export interface GetOrganizationsLackingCDEManager {
  findOrganizationsLackingCDEManager: {
    count: number;
    results: Organization[];
  };
}

export type FindOrganizationsLackingCDEManagerInput = {
  input: { accountId: number };
};

const getOrganizationsLakingCDEManagersQuery = gql`
  query findOrganizationsLackingCDEManager($input: FindAllProviderOrganizationInput!) {
    findOrganizationsLackingCDEManager(input: $input) {
      count
      results {
        id
        name
      }
    }
  }
`;

export function useFindOrganizationsLackingCDEManagerQuery(
  options?: LazyQueryHookOptions<
    GetOrganizationsLackingCDEManager,
    FindOrganizationsLackingCDEManagerInput
  >,
) {
  return useLazyQuery(getOrganizationsLakingCDEManagersQuery, options);
}
