import styled from 'styled-components';
import { IconButton, Input } from '@mui/material';
import { Tooltip } from '@getvim/atomic-ui';
import VisibilityIcon from '@mui/icons-material/Visibility';
import VisibilityOffIcon from '@mui/icons-material/VisibilityOff';
import ContentCopy from '@mui/icons-material/ContentCopy';
import { useCallback, useState } from 'react';

type SecretRowProps = {
  secret?: string;
  rotateClientSecretButton?: JSX.Element;
  isEditableSecret?: boolean;
  onEditableSecretChange?: (secret: string) => void;
  isValid?: boolean;
};

export const validateClientSecret = (secret: string) => {
  const isCorrectLength = secret.length >= 48;
  const isLengthTooLong = secret.length > 256;

  const hasUppercase = /[A-Z]/.test(secret);
  const hasLowercase = /[a-z]/.test(secret);
  const hasNumbers = /\d/.test(secret);
  const specialCharsOnly = secret.replace(/[\dA-Za-z]/g, '');
  const hasSpecialChars = /^[+.=_\-]+$/.test(specialCharsOnly);

  const isValid =
    isCorrectLength &&
    hasUppercase &&
    hasLowercase &&
    hasNumbers &&
    hasSpecialChars &&
    !isLengthTooLong;
  return {
    isValid,
    errors: {
      length: !isCorrectLength,
      uppercase: !hasUppercase,
      lowercase: !hasLowercase,
      numbers: !hasNumbers,
      specialChars: !hasSpecialChars,
      lengthTooLong: isLengthTooLong,
    },
  };
};

export const SecretRow: React.FC<SecretRowProps> = ({
  secret,
  rotateClientSecretButton,
  isEditableSecret,
  onEditableSecretChange,
  isValid,
}) => {
  const [showSecret, setShowSecret] = useState(false);
  const [errors, setErrors] = useState({
    length: false,
    uppercase: false,
    lowercase: false,
    numbers: false,
    specialChars: false,
    lengthTooLong: false,
  });

  const onVisibilityClick = useCallback(() => {
    setShowSecret((prev) => !prev);
  }, []);

  const onCopyClick = useCallback(() => {
    navigator.clipboard.writeText(secret ?? '');
  }, [secret]);

  const onOwnGeneratedSecretChanged = useCallback(
    (event) => {
      const { errors: userErrors } = validateClientSecret(event.target.value);
      setErrors(userErrors);
      if (onEditableSecretChange) {
        onEditableSecretChange(event.target.value);
      }
    },
    [onEditableSecretChange],
  );

  return (
    <>
      <SecretValueWrapper className={isValid ? 'secret-wrapper' : 'secret-wrapper error'}>
        {isEditableSecret ? (
          <Input
            className="own-generated-secret-input"
            value={secret}
            onChange={onOwnGeneratedSecretChanged}
            type={showSecret ? 'text' : 'password'}
            placeholder="Enter a new secret"
            classes={{ error: 'error' }}
            error={!isValid}
          />
        ) : (
          <OverflowingTextWithIcons className="secret-value">
            {showSecret
              ? secret
              : '****************************************************************'}
          </OverflowingTextWithIcons>
        )}
        <StyledTooltip tooltipContent={showSecret ? 'Hide' : 'Show'} placement="top">
          <IconButton
            onClick={onVisibilityClick}
            sx={{
              color: (theme) => {
                return theme.palette.primary.dark;
              },
            }}
          >
            {showSecret ? <VisibilityOffIcon /> : <VisibilityIcon />}
          </IconButton>
        </StyledTooltip>
        <StyledTooltip tooltipContent="Copy" placement="top">
          <IconButton
            onClick={onCopyClick}
            sx={{
              color: (theme) => {
                return theme.palette.primary.dark;
              },
            }}
          >
            <ContentCopy />
          </IconButton>
        </StyledTooltip>
        {rotateClientSecretButton}
      </SecretValueWrapper>
      {!isValid && (
        <div className="error-messages">
          {errors.length && <p>Secret must be at least 48 characters long.</p>}
          {errors.uppercase && <p>Secret must contain at least one uppercase letter.</p>}
          {errors.lowercase && <p>Secret must contain at least one lowercase letter.</p>}
          {errors.numbers && <p>Secret must contain at least one number.</p>}
          {errors.specialChars && (
            <p>Secret must contain at least one of these special characters: _, -, +, =, .</p>
          )}
          {errors.lengthTooLong && <p>Secret is too long, can be up to 256 characters.</p>}
        </div>
      )}
    </>
  );
};

const SecretValueWrapper = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
`;

const OverflowingText = styled.div`
  text-overflow: ellipsis;
  overflow: hidden;
  white-space: nowrap;
  width: calc(100% - 228px);
  flex-grow: 1;
`;

const OverflowingTextWithIcons = styled(OverflowingText)`
  width: calc(100% - 348px);
`;

const StyledTooltip = styled(Tooltip)`
  z-index: 100000000;
`;
