import { gql, QueryHookOptions, useLazyQuery } from '@apollo/client';
import { AuditLogRecord } from '../../types';

export interface GetAuditsInput {
  input: {
    q?: string;
    filters?: Partial<Record<'actionName' | 'organizationID' | 'actionResult' | 'appName', any>>;
    page?: number;
    limit?: number;
    sortBy?: string;
    order?: string;
  };
}

export interface GetAuditsResult {
  getAudits: AuditLogRecord[];
}

const getAuditsQuery = gql`
  query getAudits($input: GetAuditsInput) {
    getAudits(input: $input) {
      createdAt
      appName
      actionName
      actingUser {
        id {
          technicalId
          readableId
        }
        organization
        accountId
      }
      affectedEntity {
        id {
          technicalId
          readableId
        }
        organization
        accountId
        type
        affectedFields {
          name
          previousValue
          newValue
        }
      }
      sourceIp
      actionResult
      totalCount
    }
  }
`;

export function useGetAuditsLazyQuery(options: QueryHookOptions<GetAuditsResult, GetAuditsInput>) {
  return useLazyQuery(getAuditsQuery, options);
}
