import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { AddressInput, Input, Tags, User } from '../../types';

export interface UpdateUserMutation {
  updateUser: User;
}

export interface UpdateUserInput {
  id?: string;
  externalId: string;
  username?: string;
  password?: string;
  phoneNumber?: string | null;
  products?: string[];
  npi?: string | null;
  tin?: Array<string | null> | null;
  title?: string | null;
  titles?: string[] | null;
  roles?: string[] | null;
  address?: AddressInput | null;
  firstName: string;
  lastName: string;
  tag?: Tags;
  isOptOutFromVC?: boolean;
}

const updateUserMutation = gql`
  mutation updateUser($input: UpdateUserInput!) {
    updateUser(input: $input) {
      id
    }
  }
`;

export function useUpdateUserMutation(
  options?: MutationHookOptions<UpdateUserMutation, Input<UpdateUserInput>>,
) {
  return useMutation(updateUserMutation, options);
}
