import React from 'react';
import styled from 'styled-components';
import { BkmdModal } from '@getvim/atomic-ui';
import { IconButton } from './icon-button';

interface Props {
  isOpen: boolean;
  onClose?: () => void;
}

export const Modal: React.FunctionComponent<Props> = ({ isOpen, onClose, children, ...props }) => (
  <StyledModal isOpen={isOpen} handleClose={onClose} {...props}>
    {onClose && <XButton fontIconName="icon-x-2" onClick={onClose} />}
    {children}
  </StyledModal>
);

const StyledModal = styled(BkmdModal)`
  width: fit-content;
  top: 120px;
  border-radius: ${({ theme }) => theme.borderRadius};
  box-shadow: 0 15px 20px 0 ${({ theme }) => theme.colors.darkShadow};
`;

const XButton = styled(IconButton)`
  position: absolute;
  top: 12px;
  right: 12px;
`;
