import React from 'react';
import styled from 'styled-components';

interface Props {
  fontIconName: string;
  onClick: () => void;
}

export const IconButton: React.FunctionComponent<Props> = ({
  fontIconName,
  onClick,
  ...props
}: Props) => (
  <Button onClick={onClick} {...props}>
    <i className={fontIconName} />
  </Button>
);

const Button = styled.button`
  background: transparent;
  border: 0;
  display: flex;
  align-items: center;
  padding: 5px;
  border-radius: ${(props) => props.theme.borderRadius};

  :hover {
    background: ${(props) => props.theme.colors.selectionHighlight};
    cursor: pointer;
    border-radius: 50%;
  }

  i {
    font-size: ${(props) => props.theme.fontSizes.small};
    color: ${(props) => props.theme.colors.textHeading} !important;
  }
`;
