import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { SuccessResponse } from '../../types';

export interface DeletePotentialUserVariables {
  id: number;
}

export interface DeletePotentialUserMutation {
  deletePotentialUser: SuccessResponse;
}

const deletePotentialUserMutation = gql`
  mutation deletePotentialUser($id: Int!) {
    deletePotentialUser(id: $id) {
      success
    }
  }
`;

export function useDeletePotentialUserMutation(
  options?: MutationHookOptions<DeletePotentialUserMutation, DeletePotentialUserVariables>,
) {
  return useMutation(deletePotentialUserMutation, options);
}
