import { gql } from '@apollo/client';

export const GET_MARKETPLACE_APPLICATIONS = gql`
  query GetMarketplaceApps {
    getMarketplaceApplications {
      applications {
        name
        id
        version
        account {
          id
          name
          address
          phoneNumber
        }
        isCoreApp
        isPhiFree
        isInstalled
        manifest {
          metadata {
            name
            description
            url
            services {
              id
              version
              metadata {
                id
                description
                url
              }
              capabilities {
                enrichEHR {
                  allowedPII
                  resources {
                    patient
                    encounter
                    orders
                    referral
                  }
                }
                enrichUser
                custom
                allowedPII
                actions
              }
            }
            launchEndpoint
            tokenEndpoint
            allowedUrls
          }

          UI {
            icon
            iconUrl
            tooltip
            size
          }
        }
        submission {
          appVersionId
          createdAt
          appStoreListing
          marketplaceSettings
        }
        dataConnections {
          id
          name
          iconUrl
        }
        canAddApplicationDirectly
      }
    }
  }
`;
