import {
  MutationHookOptions,
  QueryHookOptions,
  gql,
  useLazyQuery,
  useMutation,
  useQuery,
} from '@apollo/client';
import { ApplicationVersionStatus, ApplicationVersionSubmission } from '@getvim-os/types';
import { Input } from '../../types';

const ApplicationVersionSubmissionResponse = gql`
  fragment ApplicationVersionSubmissionResponseFields on ApplicationVersionSubmissionResponse {
    appVersionId
    submission {
      updatedAt
      appVersionId
      applicationInformation
      testingInformation
      permissionUsage
      securityAndCompliance
      appStoreListing
      marketplaceSettings
      contacts
    }
  }
`;

const getApplicationVersionsSubmissionQuery = gql`
  ${ApplicationVersionSubmissionResponse}
  query getApplicationVersionSubmissionQuery($appVersionId: String!) {
    getApplicationVersionSubmission(appVersionId: $appVersionId) {
      ...ApplicationVersionSubmissionResponseFields
    }
  }
`;
interface GetApplicationVersionSubmissionQuery {
  getApplicationVersionSubmission: {
    submission: ApplicationVersionSubmission | null;
  };
}

export function useLazyGetApplicationVersionSubmissionQuery(
  options?: QueryHookOptions<GetApplicationVersionSubmissionQuery, { appVersionId: string }>,
) {
  return useLazyQuery(getApplicationVersionsSubmissionQuery, options);
}

export function useGetApplicationVersionSubmissionQuery(
  options?: QueryHookOptions<GetApplicationVersionSubmissionQuery, { appVersionId: string }>,
) {
  return useQuery(getApplicationVersionsSubmissionQuery, options);
}

const saveApplicationVersionSubmissionMutation = gql`
  ${ApplicationVersionSubmissionResponse}
  mutation saveApplicationVersionSubmission($input: SaveApplicationVersionSubmissionInput!) {
    saveApplicationVersionSubmission(input: $input) {
      ...ApplicationVersionSubmissionResponseFields
    }
  }
`;
export const useSaveAppSubmissionDraftMutation = () =>
  useMutation(saveApplicationVersionSubmissionMutation);

const submitApplicationVersionSubmissionMutation = gql`
  mutation submitApplicationVersionSubmissionMutation(
    $input: SubmitApplicationVersionSubmissionInput!
  ) {
    submitApplicationVersionSubmission(input: $input)
  }
`;

interface SubmitApplicationVersionSubmissionMutation {
  appVersionId: string;
}

export function useSubmitApplicationVersionSubmissionMutation(
  options?: MutationHookOptions<
    SubmitApplicationVersionSubmissionMutation,
    Input<SubmitApplicationVersionSubmissionMutation>
  >,
) {
  return useMutation(submitApplicationVersionSubmissionMutation, {
    ...options,
    update(cache) {
      cache.modify({
        id: cache.identify({
          __typename: 'ApplicationVersion',
          id: options?.variables?.input.appVersionId,
        }),
        fields: {
          status() {
            return ApplicationVersionStatus.PENDING_REVIEW;
          },
        },
      });
    },
  });
}

interface GetUploadAppStoreImagesMutation {
  getApplicationAppStoreImagesUploadLink: {
    presignedURL: string;
    downloadUrl: string;
  };
}

const getUploadAppStoreImagesMutation = gql`
  mutation getUploadAppStoreImages($fileName: String!) {
    getApplicationAppStoreImagesUploadLink(fileName: $fileName) {
      presignedURL
      downloadUrl
    }
  }
`;

export function useUploadAppStoreImagesMutation(
  options: MutationHookOptions<GetUploadAppStoreImagesMutation, { fileName: string }>,
) {
  return useMutation(getUploadAppStoreImagesMutation, options);
}
