import { History } from 'history';
import { safeLocalStorage } from '@getvim/utils-safe-storage';
import { Input, PERMISSION, PublicRoutes } from '../types';
import {
  ACCESS_TOKEN_STORAGE_KEY,
  ORGANIZATION_ADMIN_URL_PATH,
  REFRESH_TOKEN_STORAGE_KEY,
} from './constants';
import { gqlConsoleClient } from './gqlClient';
import { FetchResult, MutationTuple } from '@apollo/client';
import { RefreshTokenToConsoleMutation, RefreshTokenInput } from '../api';
import { Logger } from '@getvim-os/logger';

const REFRESH_TOKEN_INTERVAL = 20 * 60 * 1000;
const FAILED_TO_FETCH_AUTH0_TOKEN = 'Failed to fetch access token from Auth0';

class AuthManager {
  private refreshTokenInterval?: any;
  private refreshTokenMutation?: MutationTuple<
    RefreshTokenToConsoleMutation,
    Input<RefreshTokenInput>
  >[0];
  private refreshTokenRestApiCall?: (
    args: RefreshTokenInput,
  ) => RefreshTokenToConsoleMutation['refreshTokenToConsole'] | undefined;
  private shouldUseRestForPublicEndpointsFF?: boolean;
  private getAccessTokenSilently?: () => Promise<string>;
  private clearAllContextsData?: () => void;
  private onSetNewTokenObserversMap: Map<string, (accessToken: string) => void> = new Map();
  private logger?: Logger;
  public getAccessToken() {
    return safeLocalStorage.getItem(ACCESS_TOKEN_STORAGE_KEY);
  }

  public setRefreshTokenMutation(
    refreshTokenMutationInput: any,
    clearAllContextsData: () => void,
    getAccessTokenSilently: () => Promise<string>,
    refreshTokenRestApiCall: any,
    shouldUseRestForPublicEndpointsFF: boolean,
  ) {
    this.refreshTokenMutation = refreshTokenMutationInput;
    this.refreshTokenRestApiCall = refreshTokenRestApiCall;
    this.shouldUseRestForPublicEndpointsFF = shouldUseRestForPublicEndpointsFF;
    this.getAccessTokenSilently = getAccessTokenSilently;
    this.clearAllContextsData = clearAllContextsData;
    this.clearInterval();
    this.startRefreshTokenInterval();
  }

  public addOnSetNewTokenObserver(observerKey: string, observer: (accessToken: string) => void) {
    if (this.onSetNewTokenObserversMap.has(observerKey)) {
      throw new Error(`Observer with key ${observerKey} already exists`);
    }
    this.onSetNewTokenObserversMap.set(observerKey, observer);
  }

  public removeOnSetNewTokenObserver(observerKey: string) {
    return this.onSetNewTokenObserversMap.delete(observerKey);
  }

  public setNewTokens(accessToken: string, refreshToken?: string) {
    safeLocalStorage.setItem(ACCESS_TOKEN_STORAGE_KEY, accessToken);
    safeLocalStorage.setItem(REFRESH_TOKEN_STORAGE_KEY, refreshToken || '');
    this.onSetNewTokenObserversMap.forEach((observer, key) => {
      try {
        observer(accessToken);
      } catch (error) {
        if (this.logger) {
          this.logger?.error(`On set new tokens - failed to notify observer [${key}]`, error);
        } else {
          console.error(`On set new tokens - failed to notify observer [${key}]`, error);
        }
      }
    });
  }

  public removeTokens() {
    safeLocalStorage.removeItem(ACCESS_TOKEN_STORAGE_KEY);
    safeLocalStorage.removeItem(REFRESH_TOKEN_STORAGE_KEY);
  }

  public isAuthenticated(): boolean {
    /**
     * Temporary fix: Only validate token presence, not expiration
     *
     * We're skipping token expiration checks due to client-side time synchronization issues.
     * If a token is not valid, backend requests will fail and the user will be unable
     * to use the console until they re-authenticate.
     *
     * TODO: remove this once we have a proper solution for client time.
     */

    return Boolean(safeLocalStorage.getItem(ACCESS_TOKEN_STORAGE_KEY));
  }

  public isVimAdmin(accessToken?: string | null): boolean {
    return this.getUserPermissions(accessToken).includes(PERMISSION.VIM_ADMIN);
  }

  /** TODO: custom redirect doesn't work as clearAllContextsData calls logout from auth0, which redirects to Universal Login.
   *  Perhaps can logout without redirect for specific cases such as showing Error Page if consoleMe Fails */
  public logout({
    history,
    redirect,
    clearAllContextsData,
    isAuthenticatedThroughAuth0,
    logoutReason,
  }: {
    history?: History;
    redirect?: PublicRoutes;
    clearAllContextsData?: () => void;
    isAuthenticatedThroughAuth0?: boolean;
    logoutReason?: string;
  }): void {
    this.logger?.info('logout', { logoutReason });

    this.removeTokens();
    gqlConsoleClient.clearStore();
    clearAllContextsData?.();
    this.clearInterval();

    if (isAuthenticatedThroughAuth0) {
      return;
    }

    if (!redirect) {
      return;
    }

    if (history) {
      history.push(redirect);
      return;
    }

    location.replace(`${location.origin}${ORGANIZATION_ADMIN_URL_PATH}${redirect}`);
  }

  public getUserPermissions(outerAccessToken?: string | null): PERMISSION[] {
    const accessToken = outerAccessToken || safeLocalStorage.getItem(ACCESS_TOKEN_STORAGE_KEY);
    const { permissions } = AuthManager.parseJwtPayload(accessToken) || {};
    return permissions || [];
  }

  public hasPermission(permission: PERMISSION): boolean {
    const accessToken = this.getAccessToken();

    if (this.isVimAdmin(accessToken)) {
      return true;
    }

    const userPermissions = this.getUserPermissions(accessToken);

    return userPermissions.includes(permission);
  }

  public hasOneOfPermissions(permissions: PERMISSION[]): boolean {
    const accessToken = this.getAccessToken();

    if (this.isVimAdmin(accessToken)) {
      return true;
    }

    const userPermissions = this.getUserPermissions(accessToken);

    return permissions.some((permission) => userPermissions.includes(permission));
  }

  public setLogger(logger: Logger) {
    this.logger = logger;
  }

  private startRefreshTokenInterval() {
    const accessToken = this.getAccessToken();

    if (!this.isAccessTokenValidForMoreThan20Minutes(accessToken)) {
      this.refreshTokenIntervalHandler();
    }
    this.refreshTokenInterval = setInterval(async () => {
      await this.refreshTokenIntervalHandler();
    }, REFRESH_TOKEN_INTERVAL);
  }

  private isAccessTokenValidForMoreThan20Minutes(accessToken) {
    try {
      const [_, base64Payload] = accessToken.split('.');
      const { exp: expiredAtInSeconds } = JSON.parse(atob(base64Payload));
      const expiredAtInMilliseconds = expiredAtInSeconds * 1000;
      const currentTimeInMillisecondsPlusTwentyMinutes = Date.now() + REFRESH_TOKEN_INTERVAL;
      return currentTimeInMillisecondsPlusTwentyMinutes < expiredAtInMilliseconds;
    } catch {
      return false;
    }
  }

  private clearAndLogout(message?: string, error?: any) {
    if (this.logger) {
      this.logger?.error('clearAndLogout', { message, error });
    } else {
      console.error(message, error);
    }

    this.clearInterval();
    this.logout({
      clearAllContextsData: this.clearAllContextsData,
      logoutReason: message,
    });
  }

  private async refreshTokenIntervalHandler() {
    const refreshToken = safeLocalStorage.getItem(REFRESH_TOKEN_STORAGE_KEY);
    if (refreshToken) {
      let result:
        | FetchResult<RefreshTokenToConsoleMutation, Record<string, any>, Record<string, any>>
        | undefined;

      const input = { refreshToken };

      try {
        if (this.shouldUseRestForPublicEndpointsFF) {
          const restResult = await this.refreshTokenRestApiCall?.(input);

          result = restResult ? { data: { refreshTokenToConsole: restResult } } : undefined;
        } else {
          const graphqlResult = await this.refreshTokenMutation?.({
            variables: { input },
          });

          result = graphqlResult;
        }

        const { accessToken: newAccessToken, refreshToken: newRefreshToken } =
          result?.data?.refreshTokenToConsole || {};
        if (!newAccessToken || !newRefreshToken) {
          throw new Error(`result: ${JSON.stringify(result)}`);
        }
        this.setNewTokens(newAccessToken, newRefreshToken);
      } catch (error) {
        this.clearAndLogout('Refresh token result is missing tokens', error);
      }
      return;
    }
    if (this.getAccessTokenSilently) {
      let newAccessToken;
      try {
        newAccessToken = await this.getAccessTokenSilently();
      } catch (error) {
        return this.clearAndLogout(FAILED_TO_FETCH_AUTH0_TOKEN, error);
      }
      if (!newAccessToken) {
        return this.clearAndLogout(FAILED_TO_FETCH_AUTH0_TOKEN);
      }
      this.setNewTokens(newAccessToken);
    }
  }

  private clearInterval() {
    clearInterval(this.refreshTokenInterval);
  }

  private static parseJwtPayload(token: string | null) {
    if (!token) {
      return undefined;
    }
    try {
      return JSON.parse(atob(token.split('.')[1]));
    } catch {
      return undefined;
    }
  }
}

export const authManager = new AuthManager();
