import { createContext, useCallback, useContext, useEffect, useMemo } from 'react';
import { LegalDocumentMapByType, LegalDocumentType } from '../../types';
import { getVimWebsiteUrl } from '../../common';
import { useGetLatestLegalDocumentsQuery, useGetLatestLegalDocumentsRest } from '../../api';
import { useShouldUseRestForPublicEndpoints } from '../../feature-flags';

interface LegalDocumentsContextData {
  legalDocumentsMap: LegalDocumentMapByType;
  getLegalDocumentByType: (type: LegalDocumentType) => LegalDocumentMapByType[LegalDocumentType];
}

export const LegalDocumentsContext = createContext<LegalDocumentsContextData>(
  {} as LegalDocumentsContextData,
);

export const LegalDocumentsProvider = ({ children }) => {
  const context = useLegalDocumentsContextProvider();

  const { Provider } = LegalDocumentsContext;
  return <Provider value={context}>{children}</Provider>;
};

export const useLegalDocumentsContext = (): LegalDocumentsContextData =>
  useContext(LegalDocumentsContext);

export const useLegalDocumentsContextProvider = (): LegalDocumentsContextData => {
  const [shouldUseRestForPublicEndpointsFF, shouldUseRestForPublicEndpointsFFLoading] =
    useShouldUseRestForPublicEndpoints();

  const legalDocumentsGraphqlResult = useGetLatestLegalDocumentsQuery({
    skip: shouldUseRestForPublicEndpointsFF || shouldUseRestForPublicEndpointsFFLoading,
  });

  const { trigger: getLatestDocsRest, data: latestDocsRestResultData } =
    useGetLatestLegalDocumentsRest();

  const latestLegalDocuments = shouldUseRestForPublicEndpointsFF
    ? latestDocsRestResultData
    : legalDocumentsGraphqlResult.data?.getLatestLegalDocuments;

  useEffect(() => {
    if (shouldUseRestForPublicEndpointsFF) {
      getLatestDocsRest();
    }
  }, [getLatestDocsRest, shouldUseRestForPublicEndpointsFF]);

  const getLegalDocumentUrlByType = useCallback(
    (type: LegalDocumentType) => {
      const document = latestLegalDocuments?.find((document) => document.type === type);
      const url = document?.url;
      if (!url) {
        return;
      }
      return getVimWebsiteUrl(url);
    },
    [latestLegalDocuments],
  );

  const legalDocumentsMap = useMemo(() => {
    const map: LegalDocumentMapByType = {
      [LegalDocumentType.ToS]: {
        url: getLegalDocumentUrlByType(LegalDocumentType.ToS),
        name: 'Terms of Service',
      },
      [LegalDocumentType.BAA]: {
        url: getLegalDocumentUrlByType(LegalDocumentType.BAA),
        name: 'Business Associate Agreement',
      },
      [LegalDocumentType.PrivacyPolicy]: {
        url: getLegalDocumentUrlByType(LegalDocumentType.PrivacyPolicy),
        name: 'Privacy Policy',
      },
    };

    return map;
  }, [getLegalDocumentUrlByType]);

  const getLegalDocumentByType = useCallback(
    (type: LegalDocumentType) => {
      return legalDocumentsMap[type];
    },
    [legalDocumentsMap],
  );

  return { legalDocumentsMap, getLegalDocumentByType };
};
