import { gql } from '@apollo/client';

// GraphQL fragment for application fields to ensure type safety and reusability
const APPLICATION_FRAGMENT = gql`
  fragment ApplicationMarketplaceFields on MarketplaceApplication {
    id
    name
    isInstalled
    isPhiFree
    isCoreApp
    canAddApplicationDirectly
    releaseStatus
    account {
      id
      name
    }
    submission {
      marketplaceSettings
      appStoreListing
    }
    manifest {
      metadata {
        name
      }
      UI {
        iconUrl
      }
    }
    dataConnections {
      name
      accountId
    }
    version
    installs {
      total
    }
  }
`;

export const GET_MY_APPLICATIONS = gql`
  query GetMyApplications {
    myApplications {
      marketplace {
        ...ApplicationMarketplaceFields
      }
      myApps {
        ...ApplicationMarketplaceFields
      }
      connectedApps {
        ...ApplicationMarketplaceFields
      }
    }
  }
  ${APPLICATION_FRAGMENT}
`;

export const GET_MY_APPLICATIONS_BY_ACCOUNT_ID = gql`
  query AccountApplications($accountId: Int!) {
    accountApplications(accountId: $accountId) {
      marketplace {
        ...ApplicationMarketplaceFields
      }
      myApps {
        ...ApplicationMarketplaceFields
      }
      connectedApps {
        ...ApplicationMarketplaceFields
      }
    }
  }
  ${APPLICATION_FRAGMENT}
`;
