import { LazyQueryHookOptions, gql, useLazyQuery } from '@apollo/client';
import { AppConsumingUser } from '../../types';

export interface GetAllAccountApplicationsConsumingOrganizationUsersInput {
  input: {
    accountId: number;
    organizationId: number;
  };
}

export interface GetAllAccountApplicationsConsumingOrganizationUsersResponse {
  getAllAccountApplicationsConsumingOrganizationUsers: AppConsumingUser[];
}

export const getAllAccountApplicationsConsumingOrganizationUsersQuery = gql`
  query getAllAccountApplicationsConsumingOrganizationUsers(
    $input: GetAllAccountApplicationsConsumingOrganizationUsersInput!
  ) {
    getAllAccountApplicationsConsumingOrganizationUsers(input: $input) {
      id
      externalId
      organizationId
      npi
      tin
      roles
      createdAt
      activatedAt
      lastLoginAt
      lastFailedLoginAt
      address {
        addressLine1
        addressLine2
        city
        state
        zip
        fullAddress
      }
      firstName
      lastName
      email
      phoneNumber
      linkedEhrUser
      consumedApplicationIds
      isOptOutFromVC
    }
  }
`;

export const useGetAllAccountApplicationsConsumingOrganizationUsersLazyQuery = (
  options?: LazyQueryHookOptions<
    GetAllAccountApplicationsConsumingOrganizationUsersResponse,
    GetAllAccountApplicationsConsumingOrganizationUsersInput
  >,
) => useLazyQuery(getAllAccountApplicationsConsumingOrganizationUsersQuery, options);
