import { Dispatch, SetStateAction, createContext, useCallback, useContext, useState } from 'react';
import { LoginFlowStep } from '../login/loginFlowStep';

type LoginState = { justLoggedIn: boolean; queryString: string };
const DEFAULT_LOGIN_FLOW_STEP = LoginFlowStep.ReadyToAuthenticate;

export interface LoginContextData {
  loginState: LoginState | undefined;
  setLoginState: Dispatch<SetStateAction<LoginState | undefined>>;
  loginFlowStep: LoginFlowStep;
  setLoginFlowStep: Dispatch<SetStateAction<LoginFlowStep>>;
  clearLogin: () => void;
  /** did the user use credentials / sso in universal login or we authenticate from stored access token on refresh */
  isInteractiveLogin: boolean;
  setIsInteractiveLogin: Dispatch<SetStateAction<boolean>>;
}

/** Context for the login flow after the auth0 SDK is authenticated (after Universal Login redirects back to Console) */
export const LoginContext = createContext<LoginContextData>({} as LoginContextData);

export const LoginContextProvider = ({ children }) => {
  const context = useLoginContextProvider();

  const { Provider } = LoginContext;
  return <Provider value={context}>{children}</Provider>;
};

export const useLoginContext = (): LoginContextData => useContext(LoginContext);

const useLoginContextProvider = (): LoginContextData => {
  const [loginState, setLoginState] = useState<LoginState>();
  const [loginFlowStep, setLoginFlowStep] = useState(DEFAULT_LOGIN_FLOW_STEP);
  const [isInteractiveLogin, setIsInteractiveLogin] = useState(false);

  const clearLogin = useCallback(() => {
    setLoginState(undefined);
    setLoginFlowStep(DEFAULT_LOGIN_FLOW_STEP);
  }, []);

  return {
    loginState,
    setLoginState,
    loginFlowStep,
    setLoginFlowStep,
    clearLogin,
    isInteractiveLogin,
    setIsInteractiveLogin,
  };
};
