import {
  gql,
  LazyQueryHookOptions,
  QueryHookOptions,
  useLazyQuery,
  useQuery,
} from '@apollo/client';
import { AppConsumingOrganization } from '../../types/appConsumingOrganization';

export interface GetOneApplicationConsumingOrganization {
  input: {
    accountId: number;
    organizationId: number;
  };
}

export interface GetOneApplicationConsumingOrganizationResponse {
  getOneApplicationConsumingOrganization: AppConsumingOrganization;
}

export const getOneApplicationConsumingOrganization = gql`
  query getOneApplicationConsumingOrganization(
    $input: GetOneApplicationConsumingOrganizationInput!
  ) {
    getOneApplicationConsumingOrganization(input: $input) {
      id
      accountId
      accountName
      ehrUrl
      organizationKey
      identityProvider
      name
      tins
      npi
      ehrSystem
      tag
      consumedApplicationIds
      products {
        name
      }
    }
  }
`;

export const useGetOneApplicationConsumingOrganization = (
  options?: QueryHookOptions<
    GetOneApplicationConsumingOrganizationResponse,
    GetOneApplicationConsumingOrganization
  >,
) => useQuery(getOneApplicationConsumingOrganization, options);

export const useGetOneApplicationConsumingOrganizationLazy = (
  options?: LazyQueryHookOptions<
    GetOneApplicationConsumingOrganizationResponse,
    GetOneApplicationConsumingOrganization
  >,
) => useLazyQuery(getOneApplicationConsumingOrganization, options);
