import { gql, QueryHookOptions, useQuery } from '@apollo/client';
import { LegalDocument } from '../../types';
import { useAsyncAction } from '../hooks/useAsyncAction';
import { AxiosRequestConfig } from 'axios';
import { httpClient } from '../../common/httpClient';

export interface GetLatestLegalDocumentsQuery {
  getLatestLegalDocuments: LegalDocument[];
}

const getLatestLegalDocumentsQuery = gql`
  query getLatestLegalDocuments {
    getLatestLegalDocuments {
      id
      type
      url
      effectiveDate
    }
  }
`;

export function useGetLatestLegalDocumentsQuery(
  options?: QueryHookOptions<GetLatestLegalDocumentsQuery>,
) {
  return useQuery(getLatestLegalDocumentsQuery, options);
}

export function useGetLatestLegalDocumentsRest(config?: AxiosRequestConfig) {
  const status = useAsyncAction(
    async (): Promise<GetLatestLegalDocumentsQuery['getLatestLegalDocuments']> => {
      const result = await httpClient.get('/v1/legal', config);
      return result.data;
    },
  );

  return status;
}
