import React, { ForwardedRef } from 'react';
import { TextField, TextFieldProps } from '@mui/material';
import { Controller, FieldValues, ControllerProps, FieldPath } from 'react-hook-form';

export type TextInputProps<
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
> = TextFieldProps &
  Partial<ControllerProps<TFieldValues, TName>> & {
    floatingHelperText?: boolean;
    allowHelperTextOverflow?: boolean;
    name?: TName;
  };

export const TextInput = React.forwardRef(function TextInput<
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
>(
  {
    floatingHelperText,
    defaultValue,
    control,
    rules,
    shouldUnregister,
    allowHelperTextOverflow,
    ...textFieldInputProps
  }: TextInputProps<TFieldValues, TName>,
  ref: ForwardedRef<HTMLInputElement>,
) {
  const textFieldExtendedProps: TextFieldProps = {
    ...textFieldInputProps,
    ref,
    size: textFieldInputProps.size || 'small',
    error: textFieldInputProps.error !== undefined ? !!textFieldInputProps.error : undefined,
    FormHelperTextProps: {
      /* css to prevent helper text from pushing other elements when it appears.
           also allows overflowing some width, prevents helper text to be wrapped / new line when there still more width left  */
      ...textFieldInputProps.FormHelperTextProps,
      sx: {
        marginLeft: '5px',
        marginRight: '5px',
        position: floatingHelperText ? 'absolute' : undefined,
        width: allowHelperTextOverflow ? 'calc(100% + 50px)' : undefined,
        top: '36px', // small TextField
        ...textFieldInputProps.FormHelperTextProps?.sx,
      },
    },
    sx: {
      backgroundColor: '#ffffff',
      ...textFieldInputProps?.sx,
    },
  };

  if (control && textFieldInputProps.name) {
    return (
      <Controller
        name={textFieldInputProps.name}
        control={control}
        rules={rules}
        render={({ field }) => {
          return <TextField {...field} value={field.value || ''} {...textFieldExtendedProps} />;
        }}
        defaultValue={defaultValue}
      />
    );
  }

  return <TextField {...textFieldExtendedProps} defaultValue={defaultValue} />;
}) as <
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
>(
  props: TextInputProps<TFieldValues, TName> & {
    ref?: React.ForwardedRef<HTMLInputElement>;
  },
) => JSX.Element;
