export interface UpdateAppVersionMutation {
  saveApplicationVersion: {
    applicationVersion: ApplicationVersion;
  };
}
const updateAppVersionMutation = gql`
  ${ApplicationVersionResponse}
  mutation saveAppVersion($input: ApplicationVersionInput!) {
    saveApplicationVersion(input: $input) {
      applicationVersion {
        ...ApplicationVersionResponseFields
      }
    }
  }
`;

export function useUpdateAppVersionMutation(
  options?: MutationHookOptions<UpdateAppVersionMutation, Input<Partial<ApplicationVersion>>>,
) {
  return useMutation(updateAppVersionMutation, options);
}

export interface CreateAppVersionMutation {
  createApplicationVersion: {
    applicationVersion: ApplicationVersion;
  };
}

const createAppVersionMutation = gql`
  ${ApplicationVersionResponse}
  mutation createAppVersion($input: CreateApplicationVersionInput!) {
    createApplicationVersion(input: $input) {
      applicationVersion {
        ...ApplicationVersionResponseFields
      }
    }
  }
`;

export function useCreateAppVersionMutation(
  options?: MutationHookOptions<
    CreateAppVersionMutation,
    Input<Partial<ApplicationVersion> & { sourceVersionId?: string }>
  >,
) {
  return useMutation(createAppVersionMutation, {
    ...options,
    update(cache, { data }) {
      try {
        if (data?.createApplicationVersion) {
          const applicationVersionsCache = cache.readQuery<QueryApplicationVersionsResponse>({
            query: queryApplicationVersionsGQL,
            variables: {
              input: {
                appId: data.createApplicationVersion.applicationVersion.appId,
              },
            },
          });
          const updatedApplicationVersions = [
            ...(applicationVersionsCache?.queryApplicationVersions ?? []),
            data.createApplicationVersion.applicationVersion,
          ];
          cache.writeQuery<QueryApplicationVersionsResponse>({
            query: queryApplicationVersionsGQL,
            variables: {
              input: {
                appId: data.createApplicationVersion.applicationVersion.appId,
              },
            },
            data: { queryApplicationVersions: updatedApplicationVersions },
          });
          cache.writeQuery<QueryApplicationVersionsResponse>({
            query: queryApplicationVersionsGQL,
            variables: {
              input: {
                appId: data.createApplicationVersion.applicationVersion.appId,
                version: data.createApplicationVersion.applicationVersion.version,
              },
            },
            data: { queryApplicationVersions: [data.createApplicationVersion.applicationVersion] },
          });
        }
      } catch (error) {
        console.error('Failed to update cache with new application version', error);
      }
    },
  });
}

