export interface CreateAppMutationResponse {
  createApplication: {
    application: Application;
    applicationVersion: ApplicationVersion;
  };
}

export interface CreateAppMutation {
  name: string;
  accountId: number;
  description: string;
  applicationVersion: {
    applicationType: string;
    manifest: ApplicationManifest;
  };
}

export function useCreateAppMutation(
  options?: MutationHookOptions<CreateAppMutationResponse, Input<CreateAppMutation>>,
) {
  return useMutation(createAppMutation, {
    ...options,
    update(cache, { data }) {
      try {
        if (data?.createApplication) {
          // Read the current list of applications from the cache
          const getMyApplicationsCache = cache.readQuery<GetMyApplicationsQuery>({
            query: getMyApplicationsQuery,
          });

          // Add the new application to the list
          const updatedApplications = [
            ...(getMyApplicationsCache?.getMyApplications ?? []),
            data?.createApplication.application,
          ];

          // Write the updated list back to the cache
          cache.writeQuery<GetMyApplicationsQuery>({
            query: getMyApplicationsQuery,
            data: { getMyApplications: updatedApplications },
          });

          cache.writeQuery<QueryApplicationVersionsResponse>({
            query: queryApplicationVersionsGQL,
            variables: {
              input: {
                appId: data.createApplication.applicationVersion.appId,
              },
            },
            data: { queryApplicationVersions: [data.createApplication.applicationVersion] },
          });
        }
      } catch (error) {
        console.error('Failed to update cache with new application', error);
      }
    },
  });
}

interface UpdateAppMutationResponse {
  updateApplication: {
    application: Application;
  };
}

interface UpdateAppInput {
  appId: string;
  name?: string;
  description?: string;
  liveVersionId?: string;
}

const updateAppMutation = gql`
  ${ApplicationResponse}
  mutation updateApplication($input: UpdateAppInput!) {
    updateApplication(input: $input) {
      application {
        ...ApplicationResponse
      }
    }
  }
`;

export function useUpdateAppMutation(
  options?: MutationHookOptions<UpdateAppMutationResponse, Input<UpdateAppInput>>,
) {
  return useMutation(updateAppMutation, options);
}
