import { gql, LazyQueryHookOptions, useLazyQuery } from '@apollo/client';
import { DataSourceApplication } from '../../types';

export interface FindAllDataSourceApplicationsQuery {
  findAllDataSourceApplications: {
    dataSourceApplications: DataSourceApplication[];
  };
}

export interface FindAllDataSourceApplicationsInput {
  input: {
    accountId: number;
    dataSourceId: number;
  };
}

const findAllDataSourceApplicationsQuery = gql`
  query FindAllDataSourceApplications($input: FindAllDataSourceApplicationsInput!) {
    findAllDataSourceApplications(input: $input) {
      dataSourceApplications {
        id
        createdAt
        updatedAt
        dataSourceEnum
        applicationId
        config
      }
    }
  }
`;

export function useFindAllDataSourceApplicationsLazyQuery(
  options?: LazyQueryHookOptions<
    FindAllDataSourceApplicationsQuery,
    FindAllDataSourceApplicationsInput
  >,
) {
  return useLazyQuery(findAllDataSourceApplicationsQuery, options);
}
