import { ConsoleUserOrganization } from '@/types';
import { gql, LazyQueryHookOptions, useLazyQuery } from '@apollo/client';

const findOneConsoleUserOrganizationQuery = gql`
  query findOneConsoleUserOrganization($organizationId: Int!) {
    findOneConsoleUserOrganization(organizationId: $organizationId) {
      organization {
        id
        createdAt
        name
        ehrUrl
        ehrIdentifier
        tins
        npi
        organizationKey
        products {
          name
          contentSources
          isDefaultVcUserProduct
        }
        accountId
        accountName
        tag
        isOptOutFromVC
        relationTypes
        tin
        ehrSystem
        isSeamlessLoginAutoApproved
        shouldAutoCreatePotentialUsers
        identityProvider
      }
    }
  }
`;

export function useFindOneConsoleUserOrganization(
  options?: LazyQueryHookOptions<
    { findOneConsoleUserOrganization: { organization: ConsoleUserOrganization | null } },
    { organizationId: number }
  >,
) {
  return useLazyQuery(findOneConsoleUserOrganizationQuery, options);
}
