import styled from 'styled-components';

export const StepHeader: React.FC<{ title?: string }> = ({ title }) => {
  if (!title) {
    return null;
  }

  return (
    <Header data-testid="step-layout-header">
      <Text>{title}</Text>
    </Header>
  );
};

const Header = styled.div`
  width: 100%;
  height: 70px;
  padding-left: 30px;
  display: flex;
  flex-direction: column;
  justify-content: center;
`;

const Text = styled.p`
  font-size: 24px;
  font-weight: 700;
  line-height: 30px;
  color: #001c36;
`;
