import { gql, LazyQueryHookOptions, useLazyQuery } from '@apollo/client';
import { DataSource } from '../../types';

export interface FindAllDataSourcesQuery {
  findAllDataSources: {
    dataSources: DataSource[];
  };
}

export interface FindAllDataSourcesInput {
  input: {
    namespaces?: string[];
    isInsurer?: boolean;
    dataSourceEnums?: string[];
  };
}

const findAllDataSourcesQuery = gql`
  query FindAllDataSources($input: FindAllDataSourcesInput) {
    findAllDataSources(input: $input) {
      dataSources {
        id
        name
        isTest
        dataSourceEnum
        accountId
        tin
        createdAt
        updatedAt
        namespace
        type
        marketplace
        dataTransportType
        theme {
          logo {
            url
            height
            width
          }
          title {
            color
            backgroundColor
          }
        }
      }
    }
  }
`;

export function useFindAllDataSourcesLazyQuery(
  options?: LazyQueryHookOptions<FindAllDataSourcesQuery, FindAllDataSourcesInput>,
) {
  return useLazyQuery(findAllDataSourcesQuery, options);
}
