import React, { useCallback, useState } from 'react';
import styled from 'styled-components';
import { Input, InputProps } from './input';

export const PasswordInput: React.FC<InputProps> = ({ className, high, ...props }) => {
  const [passwordVisible, setPasswordVisible] = useState(false);

  const togglePasswordVisibility = useCallback(() => {
    setPasswordVisible(!passwordVisible);
  }, [passwordVisible, setPasswordVisible]);

  return (
    <div className={className}>
      <RelativeWrapper>
        <StyledInput type={passwordVisible ? 'text' : 'password'} high={high} {...props} />
        <EyeIcon
          className={passwordVisible ? 'icon-eye-3-slash' : 'icon-eye-3'}
          onClick={togglePasswordVisibility}
          highInput={high}
        />
      </RelativeWrapper>
    </div>
  );
};

const RelativeWrapper = styled.div`
  position: relative;
  color: ${(props) => props.theme.colors.textHeading};
`;

const StyledInput = styled(Input)`
  padding-right: 32px;
`;

const EyeIcon = styled(({ highInput, ...props }) => <i {...props} />)`
  position: absolute;
  right: 10px;
  top: ${({ highInput }) => (highInput ? 18 : 10)}px;
  font-size: 16px;
  font-weight: bold;
  cursor: pointer;
`;
