import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { DataSource } from '../../types';

export type UpdateDataSourceInput = { dataSourceId: number; accountId: number } & Partial<
  Pick<
    DataSource,
    | 'name'
    | 'tin'
    | 'dataSourceEnum'
    | 'namespace'
    | 'theme'
    | 'type'
    | 'dataTransportType'
    | 'marketplace'
    | 'isTest'
  >
>;

export interface UpdateDataSourceMutation {
  success?: boolean;
}

export interface UpdateDataSourceArgs {
  input: UpdateDataSourceInput;
}

export const updateDataSourceMutation = gql`
  mutation UpdateDataSource($input: UpdateDataSourceInput!) {
    updateDataSource(input: $input) {
      success
    }
  }
`;

export function useUpdateDataSourceMutation(
  options?: MutationHookOptions<UpdateDataSourceMutation, UpdateDataSourceArgs>,
) {
  return useMutation(updateDataSourceMutation, options);
}
