import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { Input, SuccessResponse } from '../../types';

export interface UpdateUserLinkedEhrUser {
  id: string;
  linkedEhrUser?: string | null;
}

export interface UpdateUserLinkedEhrUserMutation {
  updateUserLinkedEhrUser: SuccessResponse;
}

const updateUserLinkedEhrUserMutation = gql`
  mutation updateUserLinkedEhrUser($input: UpdateUserLinkedEhrUser!) {
    updateUserLinkedEhrUser(input: $input) {
      success
    }
  }
`;

export function useUpdateUserLinkedEhrUser(
  options?: MutationHookOptions<UpdateUserLinkedEhrUserMutation, Input<UpdateUserLinkedEhrUser>>,
) {
  return useMutation(updateUserLinkedEhrUserMutation, options);
}
