import { DialogActions, Typography } from '@mui/material';
import React, { useCallback, useEffect } from 'react';
import { Button, ConfirmationDialog } from '../common';
import lockedSvg from '../../assets/icons/locked.svg';
import { authManager } from '../../common';
import { useHistory } from 'react-router';
import { useClearAllContexts } from '../../hooks';
import styled from '@emotion/styled';
import { useAuth0 } from '@auth0/auth0-react';
import { useLogger } from '../providers';

export const AccountNotActivatedDialog = () => {
  const history = useHistory();
  const { clearAll } = useClearAllContexts();
  const { isAuthenticated } = useAuth0();
  const logger = useLogger({ scope: 'AccountNotActivatedDialog' });

  useEffect(() => {
    logger.info('AccountNotActivatedDialog render', {
      isAuthenticated,
    });
  }, [isAuthenticated, logger]);

  const onLogoutClick = useCallback(
    (event: React.MouseEvent) => {
      event.preventDefault();

      authManager.logout({
        history,
        clearAllContextsData: clearAll,
        isAuthenticatedThroughAuth0: isAuthenticated,
        logoutReason: 'accountNotActivatedLogoutClick',
      });
    },
    [history, clearAll, isAuthenticated],
  );

  return (
    <ConfirmationDialog
      open
      paperSx={{
        width: 400,

        padding: '34px 23px 8px 23px',
        boxSizing: 'border-box',
      }}
    >
      <Typography fontWeight={700} fontSize="24px" lineHeight="30px" marginBottom="0.5em">
        This account is not activated yet
      </Typography>
      <Typography fontWeight={500} fontSize="14px" lineHeight="21px">
        For more details please contact the Vim point of contact in your organization
      </Typography>
      <LockedImage src={lockedSvg} alt="This account is not activated yet" />
      <DialogActions>
        <Button
          style={{ marginLeft: 'auto', marginRight: 'auto', marginTop: '20px' }}
          onClick={onLogoutClick}
        >
          Logout
        </Button>
      </DialogActions>
    </ConfirmationDialog>
  );
};

const LockedImage = styled.img`
  width: fit-content;
  margin-left: auto;
  margin-right: auto;
  margin-top: 27px;
  margin-bottom: 10px;
`;
