import { gql } from '@apollo/client';
import { GqlClientQueryOptions, gqlClientQuery } from '../../common/gqlClient';
import { IsExist } from '../../types';

export interface DoesPhoneNumberExistQuery {
  doesPhoneNumberExist: IsExist;
}

export interface DoesPhoneNumberExistVariables {
  phoneNumber: string;
}

const doesPhoneNumberExistQuery = gql`
  query doesPhoneNumberExist($phoneNumber: String!) {
    doesPhoneNumberExist(phoneNumber: $phoneNumber) {
      isExist
    }
  }
`;

export const doesPhoneNumberExist = async (
  phoneNumber: string,
  options?: GqlClientQueryOptions,
) => {
  return (
    await gqlClientQuery<DoesPhoneNumberExistQuery, DoesPhoneNumberExistVariables>(
      doesPhoneNumberExistQuery,
      { phoneNumber },
      { fetchPolicy: 'no-cache', ...options },
    )
  )?.doesPhoneNumberExist;
};
