import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { DataSource, Input } from '../../types';

export type CreateDataSourceInput = Pick<
  DataSource,
  | 'accountId'
  | 'name'
  | 'tin'
  | 'dataSourceEnum'
  | 'namespace'
  | 'theme'
  | 'type'
  | 'dataTransportType'
  | 'isTest'
>;
export interface CreateDataSourceResponse {
  createDataSource: { success?: boolean };
}

export const createDataSourceMutation = gql`
  mutation CreateDataSource($input: CreateDataSourceInput!) {
    createDataSource(input: $input) {
      success
    }
  }
`;

export function useCreateDataSourceMutation(
  options?: MutationHookOptions<CreateDataSourceResponse, Input<CreateDataSourceInput>>,
) {
  return useMutation(createDataSourceMutation, options);
}
