import {
  gql,
  LazyQueryHookOptions,
  QueryHookOptions,
  useLazyQuery,
  useQuery,
} from '@apollo/client';
import { DsConsumingOrganization } from '../../types/consuming-organization';

export interface FindOneDsConsumingOrganizationInput {
  input: {
    accountId: number;
    dataSourceId: number;
    organizationId: number;
  };
}

export interface FindOneDsConsumingOrganizationResponse {
  findOneDsConsumingOrganization: DsConsumingOrganization;
}

export const findOneDsConsumingOrganizationQuery = gql`
  query FindOneDsConsumingOrganization($input: FindOneDsConsumingOrganizationInput!) {
    findOneDsConsumingOrganization(input: $input) {
      id
      consumedDsId
      accountId
      createdAt
      products {
        name
        displayName
        sources
        providerSources
        contentSources
      }
      name
      tin
      npi
      ehrSystem
      ehrUrl
      organizationKey
      tag
    }
  }
`;

export const useFindOneDsConsumingOrganization = (
  options?: QueryHookOptions<
    FindOneDsConsumingOrganizationResponse,
    FindOneDsConsumingOrganizationInput
  >,
) => useQuery(findOneDsConsumingOrganizationQuery, options);

export const useFindOneDsConsumingOrganizationLazy = (
  options?: LazyQueryHookOptions<
    FindOneDsConsumingOrganizationResponse,
    FindOneDsConsumingOrganizationInput
  >,
) => useLazyQuery(findOneDsConsumingOrganizationQuery, options);
