import { getStandAloneLogger, type LogMetadata } from '@getvim-os/logger';
import React, { createContext, useContext, useEffect, useState } from 'react';
import { useUserContext } from './user-provider';

const LoggerContext = createContext<Partial<LogMetadata>>({});

export const LoggerProvider: React.FC = ({ children }) => {
  const { user } = useUserContext();
  const [logMetadata, setLogMetadata] = useState<Partial<LogMetadata>>({});
  useEffect(() => {
    setLogMetadata({
      osUsername: user?.email,
      organizationId: user?.organization?.id,
      organization_name: user?.organization?.name,
    });
  }, [user?.email, user?.organization?.id, user?.organization?.name]);
  return <LoggerContext.Provider value={logMetadata}>{children}</LoggerContext.Provider>;
};

export const useLogger = ({ scope }: { scope: string }) => {
  const logMetadata = useContext(LoggerContext);
  const [logger] = useState(() => getStandAloneLogger(scope, logMetadata));
  useEffect(() => {
    logger.updateMetadata(logMetadata);
  }, [logMetadata, logger]);
  return logger;
};
