import { gql } from '@apollo/client';
import { times } from 'lodash-es';
import { gqlClientQuery } from '../../common';
import { Organization, ConsoleUserOrganization } from '../../types';

export interface GetConsoleUserOrganizationsQuery {
  findAllConsoleUserOrganizations: {
    totalRows: number;
    results: ConsoleUserOrganization[];
  };
}

const findAllConsoleUserOrganizationsQuery = gql`
  query findAllConsoleUserOrganizations($input: FindAllConsoleUserOrganizationsInput!) {
    findAllConsoleUserOrganizations(input: $input) {
      totalRows
      results {
        id
        createdAt
        name
        ehrSystem
        ehrUrl
        ehrIdentifier
        tins
        npi
        organizationKey
        products {
          name
          contentSources
        }
        accountId
        accountName
        tag
        isOptOutFromVC
        relationTypes
      }
    }
  }
`;

const batchSize: number = intEnvVarOrDefault(
  window.$vim_environment.VIM_ORGANIZATIONS_BATCH_SIZE as string,
  1500,
);

const firstPageSize: number = intEnvVarOrDefault(
  window.$vim_environment.VIM_ORGANIZATIONS_FIRST_PAGE_SIZE as string,
  500,
);

export async function findAllConsoleUserOrganizationsBatches(): Promise<Organization[]> {
  const res = await gqlClientQuery<GetConsoleUserOrganizationsQuery>(
    findAllConsoleUserOrganizationsQuery,
    {
      input: {
        offset: 0,
        limit: firstPageSize,
        includeAccounts: true,
        includeExtendedProperties: true,
      },
    },
    {
      fetchPolicy: 'no-cache',
    },
  );

  const firstPageResultsCount = res.findAllConsoleUserOrganizations?.results?.length || 0;
  const firstPage = res.findAllConsoleUserOrganizations.results;
  const totalItems = res.findAllConsoleUserOrganizations.totalRows;

  let consoleUserOrgs: ConsoleUserOrganization[] | undefined;

  if (firstPageResultsCount < firstPageSize || totalItems <= firstPageSize) {
    consoleUserOrgs = firstPage;
  } else {
    const totalPagesRemaining = Math.ceil((totalItems - firstPageResultsCount) / batchSize);
    const pagesArray = times(totalPagesRemaining);

    const orgsFromRemainingBatches = await Promise.all(
      pagesArray.map(async (_value, page) => {
        const offset = firstPageSize + page * batchSize;
        const res = await gqlClientQuery<GetConsoleUserOrganizationsQuery>(
          findAllConsoleUserOrganizationsQuery,
          {
            input: {
              offset,
              limit: batchSize,
              includeAccounts: true,
              includeExtendedProperties: true,
            },
          },
          {
            fetchPolicy: 'no-cache',
          },
        );

        return res.findAllConsoleUserOrganizations?.results;
      }),
    );

    consoleUserOrgs = [...firstPage, ...orgsFromRemainingBatches.flat()];
  }

  const transformedOrgs = convertConsoleUserOrgListToOrganizationList(consoleUserOrgs);

  return transformedOrgs;
}

function convertConsoleUserOrgToOrganization(
  consoleUserOrg: ConsoleUserOrganization,
): Organization {
  const transformedOrg = {
    ...consoleUserOrg,
    account: consoleUserOrg.accountName ? { name: consoleUserOrg.accountName } : undefined,
  };

  return transformedOrg;
}

function convertConsoleUserOrgListToOrganizationList(
  consoleUserOrgsList: ConsoleUserOrganization[] | undefined,
): Organization[] {
  return (
    consoleUserOrgsList?.map((consoleUserOrg) => {
      return convertConsoleUserOrgToOrganization(consoleUserOrg);
    }) || []
  );
}

function intEnvVarOrDefault(envVar: string, defaultValue: number) {
  const parsedEnvValue: number = Number.parseInt(envVar, 10);

  return Number.isNaN(parsedEnvValue) ? defaultValue : parsedEnvValue;
}
