import { AccountFlowStepType } from '@/types';
import { gql, MutationOptions, useMutation } from '@apollo/client';

const updateStepMutation = gql`
  mutation UpdateStep($input: UpdateStepInput!) {
    updateStep(input: $input) {
      success
    }
  }
`;

type UpdateStepInput = {
  input: {
    flowId: number;
    stepId: number;
    accountId: number;
    stepData: {
      stepType: AccountFlowStepType;
      data: Record<string, any>;
    };
  };
};

export interface UpdateStepResponse {
  updateStep: { success?: boolean };
}

export const useUpdateStepMutation = (
  options?: MutationOptions<UpdateStepResponse, UpdateStepInput>,
) => useMutation(updateStepMutation, options);

const updateSignTosMutation = gql`
  mutation UpdateSignTos($input: UpdateStepInput!) {
    updateSignTos(input: $input) {
      success
    }
  }
`;
// SignTos is a special case of a step that both admins and owners can complete
export const useUpdateSignTosMutation = (
  options?: MutationOptions<UpdateStepResponse, UpdateStepInput>,
) => useMutation(updateSignTosMutation, options);
