import { gql, MutationHookOptions, useMutation } from '@apollo/client';

export interface SetAndReplaceAccountOwnerVariables {
  input: SetAndReplaceAccountOwnerInput;
}

export interface SetAndReplaceAccountOwnerInput {
  accountId: number;
  email: string;
}
export interface SetAndReplaceAccountOwnerResult {
  success?: boolean;
}

const setAndReplaceAccountOwnerMutation = gql`
  mutation setAndReplaceAccountOwner($input: SetAndReplaceAccountOwnerInput!) {
    setAndReplaceAccountOwner(input: $input) {
      success
    }
  }
`;

export function useSetAndReplaceAccountOwnerMutation(
  options?: MutationHookOptions<
    SetAndReplaceAccountOwnerResult,
    SetAndReplaceAccountOwnerVariables
  >,
) {
  return useMutation(setAndReplaceAccountOwnerMutation, options);
}
