import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { DataSourceApplication } from '../../types';

export type DeleteDataSourceApplicationInput = {
  accountId: number;
  dataSourceId: number;
} & Pick<DataSourceApplication, 'applicationId'>;

export interface DeleteDataSourceApplicationMutation {
  success?: boolean;
}

export interface DeleteDataSourceApplicationArgs {
  input: DeleteDataSourceApplicationInput;
}

export const deleteDataSourceApplicationMutation = gql`
  mutation DeleteDataSourceApplication($input: DeleteDataSourceApplicationInput!) {
    deleteDataSourceApplication(input: $input) {
      success
    }
  }
`;

export function useDeleteDataSourceApplicationMutation(
  options?: MutationHookOptions<
    DeleteDataSourceApplicationMutation,
    DeleteDataSourceApplicationArgs
  >,
) {
  return useMutation(deleteDataSourceApplicationMutation, options);
}
