/** Describes the authentication status of the app, after auth0 is authenticated. Used to avoid useEffect calls during getAccessTokenSilently promise */
export enum LoginFlowStep {
  ReadyToAuthenticate = 'readyToAuthenticate',
  AuthInProgress = 'inProgress',
  AuthSuccess = 'success',
  MeSuccess = 'meSuccess',
  AllPostLoginDataCalled = 'allPostLoginDataCalled',
  Error = 'error',
}
