import { gql, MutationHookOptions, useMutation } from '@apollo/client';
import { DataSourceApplication } from '../../types';

export type UpdateDataSourceApplicationInput = {
  accountId: number;
  dataSourceId: number;
} & Pick<DataSourceApplication, 'applicationId' | 'config'>;

export interface UpdateDataSourceApplicationMutation {
  success?: boolean;
}

export interface UpdateDataSourceApplicationArgs {
  input: UpdateDataSourceApplicationInput;
}

export const updateDataSourceApplicationMutation = gql`
  mutation UpdateDataSourceApplication($input: UpdateDataSourceApplicationInput!) {
    updateDataSourceApplication(input: $input) {
      success
    }
  }
`;

export function useUpdateDataSourceApplicationMutation(
  options?: MutationHookOptions<
    UpdateDataSourceApplicationMutation,
    UpdateDataSourceApplicationArgs
  >,
) {
  return useMutation(updateDataSourceApplicationMutation, options);
}
