import { gql } from '@apollo/client';
import { GqlClientQueryOptions, gqlClientQuery } from '../../common/gqlClient';
import { Input, IsExist } from '../../types';

export interface DoesLinkedEhrUserExistQuery {
  doesLinkedEhrUserExist: IsExist;
}

export interface DoesLinkedEhrUserExist {
  organizationId: number;
  linkedEhrUser: string;
}

const doesLinkedEhrUserExistQuery = gql`
  query doesLinkedEhrUserExist($input: DoesEhrUserExistInput!) {
    doesLinkedEhrUserExist(input: $input) {
      isExist
    }
  }
`;

export const doesLinkedEhrUserExist = async (
  input: DoesLinkedEhrUserExist,
  options?: GqlClientQueryOptions,
) => {
  return (
    await gqlClientQuery<DoesLinkedEhrUserExistQuery, Input<DoesLinkedEhrUserExist>>(
      doesLinkedEhrUserExistQuery,
      { input: { ...input, linkedEhrUser: input.linkedEhrUser?.trim() } },
      { fetchPolicy: 'no-cache', ...options },
    )
  )?.doesLinkedEhrUserExist;
};
