import { gql } from '@apollo/client';
import { GqlClientQueryOptions, gqlClientQuery } from '../../common';

export interface GetPreSignedUrlForLogoUploadInput {
  input: {
    accountId: number;
    dataSourceId: number;
    fileType: 'png' | 'svg';
  };
}

export interface GetPreSignedUrlForLogoUploadResponse {
  getPreSignedUrlForLogoUpload: {
    url: string;
  };
}

export const getPreSignedUrlForLogoUploadQuery = gql`
  query getPreSignedUrlForLogoUpload($input: getPreSignedUrlForLogoUploadInput!) {
    getPreSignedUrlForLogoUpload(input: $input) {
      url
    }
  }
`;

export const getPreSignedUrlForLogoUpload = async (
  input: GetPreSignedUrlForLogoUploadInput['input'],
  options?: GqlClientQueryOptions,
) => {
  return (
    await gqlClientQuery<GetPreSignedUrlForLogoUploadResponse, GetPreSignedUrlForLogoUploadInput>(
      getPreSignedUrlForLogoUploadQuery,
      {
        input: {
          accountId: input.accountId,
          dataSourceId: input.dataSourceId,
          fileType: input.fileType,
        },
      },
      { fetchPolicy: 'no-cache', ...options },
    )
  )?.getPreSignedUrlForLogoUpload?.url;
};
