import { cn } from '../../lib/utils';
import { VariantProps, cva } from 'class-variance-authority';
import { forwardRef, InputHTMLAttributes } from 'react';

const inputVariants = cva(
  'flex h-9 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 disabled:border-opacity-30 disabled:text-gray-500',
  {
    variants: {
      variant: {
        gray: 'text-gray-6 placeholder:text-gray-7',
      },
      text: {
        small: 'text-sm placeholder:text-sm',
      },
      font: {
        light: 'font-medium placeholder:font-normal',
      },
      border: {
        blue: 'border-blue-6',
        black: 'border-black',
        red: 'border-rose-400',
      },
    },
    defaultVariants: {
      variant: 'gray',
      text: 'small',
      font: 'light',
      border: 'black',
    },
  },
);

export interface InputProps
  extends InputHTMLAttributes<HTMLInputElement>,
    VariantProps<typeof inputVariants> {
  asChild?: boolean;
}

const Input = forwardRef<HTMLInputElement, InputProps>(
  ({ className, type, variant, font, border, ...props }, ref) => {
    return (
      <input
        type={type}
        className={cn(inputVariants({ variant, font, border, className }), className)}
        ref={ref}
        {...props}
      />
    );
  },
);
Input.displayName = 'Input';

export { Input };
