import { createContext, useContext, useState, useEffect, useCallback, useMemo } from 'react';
import { ApolloError } from '@apollo/client';
import { Product } from '@getvim-os/types';
import { useToast } from '../toast';
import { AccountAppStatus, Key, ToastStatus } from '../../types';
import {
  useFindOrganizationsLackingCDEManagerQuery,
  useFindUsagesOfAppByAccountIdLazyQuery,
} from '../../api';
import { authManager, removeKeyFromObject } from '../../common';
import { useAccountContext } from './account-provider/AccountProvider';
import useLocalStorage from 'react-localstorage-hook';
import { useUserContext } from './user-provider';

interface CdeStatusContextData {
  cdeStatus: AccountAppStatus | undefined;
  isLoadingCdeStatus: boolean;
  fetchCdeStatusError: ApolloError | undefined;
  didDismissCdeNotificationBanner: boolean;
  shouldShowCdeBanner: boolean;
  setDidDismissCdeNotificationBanner: (dismissed: boolean) => void;
  refetchCdeStatus: () => void;
  clearCdeStatus: () => void;
  organizationsLackingCDEManagerCount: number | null;
}

export const CdeStatusContext = createContext<CdeStatusContextData>({
  accountId: undefined,
  cdeStatus: undefined,
  isLoadingCdeStatus: false,
  fetchCdeStatusError: undefined,
  didDismissCdeNotificationBanner: false,
  shouldShowCdeBanner: false,
  setDidDismissCdeNotificationBanner: (_) => {},
  refetchCdeStatus: () => {},
  clearCdeStatus: () => {},
  organizationsLackingCDEManagerCount: null,
} as CdeStatusContextData);

export const CdeStatusProvider = ({ children }) => {
  const context = useCdeStatusContextProvider();

  const { Provider } = CdeStatusContext;
  return <Provider value={context}>{children}</Provider>;
};

export const useCdeStatusContext = (): CdeStatusContextData => useContext(CdeStatusContext);

const useCdeStatusContextProvider = (): CdeStatusContextData => {
  const { user } = useUserContext();
  const { account } = useAccountContext();

  const [didDismissCdeNotificationBannerMap, setDidDismissCdeNotificationBannerMap] =
    useLocalStorage(Key.DID_DISMISS_CDE_NOTIFICATION_BANNER, {});

  const didDismissCdeNotificationBanner = useMemo(() => {
    if (!user?.email) {
      return true;
    }
    const didUserDismiss = didDismissCdeNotificationBannerMap?.[user.email];
    return !!didUserDismiss;
  }, [user, didDismissCdeNotificationBannerMap]);

  const setDidDismissCdeNotificationBanner = useCallback(
    (dismissed: boolean) => {
      if (!user?.email) {
        return;
      }
      // Notice this is not a useState! this is a localStorage state!
      // You cannot use the setState((currentState) => ...) format
      // Do not add didDismissCdeNotificationBannerMap as a dependency as it will cause a loop
      setDidDismissCdeNotificationBannerMap({
        ...didDismissCdeNotificationBannerMap,
        [user.email!]: dismissed,
      });
    },
    [setDidDismissCdeNotificationBannerMap, user?.email],
  );
  const [toast] = useToast();

  const [organizationsLackingCDEManagerCount, setOrganizationsLackingCDEManagerCount] = useState<
    number | null
  >(null);
  const [cdeStatus, setCdeStatus] = useState<AccountAppStatus | undefined>();

  const [findCdeStatus, { data, error: fetchCdeStatusError, loading: isLoadingCdeStatus }] =
    useFindUsagesOfAppByAccountIdLazyQuery({
      fetchPolicy: 'no-cache',
      onCompleted: (data) => {
        if (data?.findUsagesOfAppByAccountId) {
          setCdeStatus(removeKeyFromObject(data.findUsagesOfAppByAccountId, '__typename'));
        }
      },
    });

  const [findOrganizationsLackingCDEManager] = useFindOrganizationsLackingCDEManagerQuery({
    fetchPolicy: 'no-cache',
    onCompleted: (data) => {
      if (data?.findOrganizationsLackingCDEManager?.count) {
        setOrganizationsLackingCDEManagerCount(
          data.findOrganizationsLackingCDEManager.count as number,
        );
      } else {
        setOrganizationsLackingCDEManagerCount(null);
      }
    },
  });

  const fetchCdeStatus = useCallback(() => {
    if (!account?.id) {
      return;
    }
    findCdeStatus({
      variables: {
        input: { accountId: account?.id, appId: Product.CDE },
      },
    });
  }, [findCdeStatus, account?.id]);

  const accountId = account?.id;

  const isVimAdmin = authManager.isVimAdmin();

  const isCdeStatusNeeded = useMemo(() => {
    if (!user?.email) {
      return false;
    }
    return !!accountId && !!account.isActive;
  }, [account?.isActive, user?.email, accountId, didDismissCdeNotificationBanner, isVimAdmin]);

  const refetchCdeStatus = useCallback(() => {
    if (!isCdeStatusNeeded) {
      return;
    }

    fetchCdeStatus();

    if (account?.id) {
      findOrganizationsLackingCDEManager({
        variables: { input: { accountId: account.id } },
      });
    }
  }, [isCdeStatusNeeded, fetchCdeStatus, findOrganizationsLackingCDEManager, account?.id]);

  const clearCdeStatus = useCallback(() => {
    setCdeStatus(undefined);
  }, []);

  useEffect(() => {
    if (data?.findUsagesOfAppByAccountId) {
      setCdeStatus(data?.findUsagesOfAppByAccountId);
    }
  }, [data?.findUsagesOfAppByAccountId]);

  useEffect(() => {
    if (fetchCdeStatusError) {
      toast({ status: ToastStatus.error, text: 'Error occurred while fetching cdeStatus data' });
    }
  }, [fetchCdeStatusError, toast]);

  useEffect(() => {
    if (isCdeStatusNeeded) {
      refetchCdeStatus();
    }
  }, [isCdeStatusNeeded, refetchCdeStatus]);

  const shouldShowCdeBanner = useMemo(
    () => !isVimAdmin && !didDismissCdeNotificationBanner && !isCdeStatusNeeded,
    [isVimAdmin, didDismissCdeNotificationBanner, isCdeStatusNeeded],
  );
  return {
    cdeStatus,
    isLoadingCdeStatus,
    fetchCdeStatusError,
    didDismissCdeNotificationBanner,
    shouldShowCdeBanner,
    setDidDismissCdeNotificationBanner,
    refetchCdeStatus,
    clearCdeStatus,
    organizationsLackingCDEManagerCount,
  };
};
