import { gql, MutationHookOptions, useMutation } from '@apollo/client';

export interface DeleteConsoleUserVariables {
  input?: DeleteConsoleUserInput;
}

export interface DeleteConsoleUserInput {
  accountId: number;
  externalId: string;
  deletionReason?: string;
}
export interface DeleteConsoleUserResult {
  success?: boolean;
}

const deleteConsoleUserMutation = gql`
  mutation DeleteConsoleUser($input: DeleteConsoleUserInput!) {
    deleteConsoleUser(input: $input) {
      success
    }
  }
`;

export function useDeleteConsoleUserMutation(
  options?: MutationHookOptions<DeleteConsoleUserResult, DeleteConsoleUserVariables>,
) {
  return useMutation(deleteConsoleUserMutation, options);
}
